export default [{"id":3429,"question":"صلى الظهر ركعتين ثم نُبّه، فهل له أن يأتي بتكبيرة الإحرام، والاستفتاح، أو يأتي بالركعتين المتبقية مباشرة؟","title":"هل يستفتح مَنْ سَهَا عن ركعة أو أكثر ثم تَنَبّه؟","answer":"الجواب: يأتي بالركعتين مباشرة، ويكفي، ينهض بتكبير.","link":"https://binbaz.org.sa/fatwas/23603/هل-يستفتح-من-سها-عن-ركعة-او-اكثر-ثم-تنبه","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/صلى الظهر ركعتين ثم نُبّه فهل له أن يأتي بتكبيرة الإحرام، والاستفتاح.mp3","categories":["التكبير والاستفتاح"]},{"id":3534,"question":"هل يجوز للمأموم أن يسبق الإمام بتكبيرة الإحرام؟","title":"حكم استباق الإمام بتكبيرة الإحرام","answer":"الجواب: لا ما يجوز عند جميع أهل العلم، لا بد تكون بعده، إذا كبّر فكبّروا.","link":"https://binbaz.org.sa/fatwas/23715/حكم-استباق-الامام-بتكبيرة-الاحرام","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/حكم استباق الإمام بتكبيرة الإحرام.mp3","categories":["التكبير والاستفتاح"]},{"id":4551,"question":"... الأفضل بإطلاق: سبحانك اللهم وبحمدك؟","title":"ما الأفضل في أدعية الاستفتاح بالصلاة؟","answer":"الجواب: هذا من الاختيار لا شكَّ أنَّ له وجاهةً، كون... عمر والصديق -وصحَّ عنه- وعثمان وابن مسعود من حديث عائشة، من حديث أبي سعيد، كل هذا جاء من هذه الطرق يدل على أنه أساس عظيم، وأصل عظيم... يعلمه الناس.  قد يفهم ما قاله المؤلف أنه أفضل، لكن ليس بصريحٍ، قد يكون فعله عمر؛ لأنه أخصر يسهل على العامَّة حفظه، هذا الذكر سهل على العامَّة، بخلاف بقية الاستفتاحات، وليس كل أحدٍ يستطيع حفظه، ولا سيما العامَّة، ولعلَّ عمر رضي الله عنه وأرضاه اختاره لأنه ثناء على الله، محل ثناء، والاختصار أيضًا، ويسهل على مَن سمع من العامَّة والخاصَّة حفظه، وليس ذلك لأنه الأفضل، بل لهذا المعنى، و... ما نقله المؤلف، وعلى كل حالٍ فالسنة العمل بالدليل، السنة العمل بالدليل.","link":"https://binbaz.org.sa/fatwas/24831/ما-الافضل-في-ادعية-الاستفتاح-بالصلاة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/استفتاح الصلاة بقول سبحانك اللهم وبحمدك، وتبارك اسمك...mp3","categories":["التكبير والاستفتاح"]},{"id":4562,"question":"إذا نسي [أن] يُكبِّر أثناء السجود وهو مأموم؟","title":"حكم المأموم إذا نسي أن يُكبِّر أثناء السجود","answer":"الجواب: تسقط عنه، تبع الإمام.","link":"https://binbaz.org.sa/fatwas/24844/حكم-الماموم-اذا-نسي-ان-يكبر-اثناء-السجود","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/حكم المأموم إذا نسي أن يُكبِّر أثناء السجود.mp3","categories":["التكبير والاستفتاح"]},{"id":4605,"question":"يُكبِّر للركعة الفائتة إذا سلَّم عن ثلاثٍ من أربعٍ وأتى بالركعة يُكبِّر لها؟","title":"إذا سلَّم عن ثلاثٍ ثم أتى بالفائتة هل يُكبِّر لها؟","answer":"الجواب: ما له أصل، قد كبَّر حين قام من السجدة الثانية، يقف بنية الصلاة ويكمل، ويقف معه بنية الصلاة.","link":"https://binbaz.org.sa/fatwas/24894/اذا-سلم-عن-ثلاث-ثم-اتى-بالفاىتة-هل-يكبر-لها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/إذا سلَّم عن ثلاثٍ من أربعٍ وأتى بالركعة فهل يُكبِّر للركعة الفائتة.mp3","categories":["سجود السهو","التكبير والاستفتاح"]},{"id":5439,"question":"يعني كل الاستفتاحات تقال؟","title":"كيف يكون التنويع بين أدعية استفتاح الصلاة؟","answer":"الجواب: قل ما شئتَ، لا ضرر، صلُّوا كما رأيتُموني أُصلِّي. س: لكن ما كان منها طويلًا؟ ج: الطويل يليق بالتهجد من الليل. س: الطويل في الصلاة الجهرية؟ ج: في الصلاة الجهرية التطويل قد يشقُّ على بعض الناس بعض الشيء. س: إذا كان مأمومًا: قد يكون يقرأ الاستفتاح والإمام يقرأ الفاتحة؟ ج: لا، يقرأ استفتاحًا مختصرًا حتى يُنصت.[1]","link":"https://binbaz.org.sa/fatwas/31234/كيف-يكون-التنويع-بين-ادعية-استفتاح-الصلاة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/alwabel _alsaib 055.mp3","categories":["التكبير والاستفتاح"]},{"id":5703,"question":"الصلاة في النعال؟","title":"مشروعية الصلاة بالنعال","answer":"الجواب:  سنة وقربة وطاعة إذا كانت نظيفة سليمة، ولكن لما جاءت المفارش هذه، وصار الناس يدوسونها، ويقذرونها على الناس، وأكثر الناس لا يبالي بنعليه، ولا يعتني بها، فيحملها، ويجعلها في مكان خاص حتى لا يقذر الفرش على الناس؛ لأن أكثر الناس لا يبالون، ولا يعتنون بالنعال، وليس عندهم بصيرة بهذا، ولما كانت المساجد الأولى حصباء، ورمل ما يضرها ذلك.  والواجب دائمًا ألا يدخل المسجد إلا بعناية، وينظر نعليه عند دخول المسجد حتى لا يكون فيها قذر تقذر المسجد، ولو كان بطحاء، ولو كان المسجد حصباء، ليس له دخول المسجد إلا بعد النظر في نعليه، وقلبها حتى يزيل ما بها من أذى، ثم يصلي بها لا بأس، كما صلى بها النبي ﷺ. لكن اليوم بعدما فرشت المساجد، وصار فيها فرش ثمينة، وأقل شيء يؤثر فيها، وربما نفر الناس من الصلاة عليها، وأداء الجماعة، فينبغي للمؤمن ألا ينفر الناس، بل يكون عونًا لهم على أداء الجماعة، ويحفظ نعليه في مكان آخر.","link":"https://binbaz.org.sa/fatwas/1009/مشروعية-الصلاة-بالنعال","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk1_35.mp3","categories":["التكبير والاستفتاح","سنن الصلاة"]},{"id":5709,"question":"الصلاة في النعال؟","title":"مشروعية الصلاة بالنعال","answer":"الجواب:  سنة وقربة وطاعة إذا كانت نظيفة سليمة، ولكن لما جاءت المفارش هذه، وصار الناس يدوسونها، ويقذرونها على الناس، وأكثر الناس لا يبالي بنعليه، ولا يعتني بها، فيحملها، ويجعلها في مكان خاص حتى لا يقذر الفرش على الناس؛ لأن أكثر الناس لا يبالون، ولا يعتنون بالنعال، وليس عندهم بصيرة بهذا، ولما كانت المساجد الأولى حصباء، ورمل ما يضرها ذلك.  والواجب دائمًا ألا يدخل المسجد إلا بعناية، وينظر نعليه عند دخول المسجد حتى لا يكون فيها قذر تقذر المسجد، ولو كان بطحاء، ولو كان المسجد حصباء، ليس له دخول المسجد إلا بعد النظر في نعليه، وقلبها حتى يزيل ما بها من أذى، ثم يصلي بها لا بأس، كما صلى بها النبي ﷺ. لكن اليوم بعدما فرشت المساجد، وصار فيها فرش ثمينة، وأقل شيء يؤثر فيها، وربما نفر الناس من الصلاة عليها، وأداء الجماعة، فينبغي للمؤمن ألا ينفر الناس، بل يكون عونًا لهم على أداء الجماعة، ويحفظ نعليه في مكان آخر.","link":"https://binbaz.org.sa/fatwas/1009/مشروعية-الصلاة-بالنعال","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk1_35.mp3","categories":["التكبير والاستفتاح","سنن الصلاة"]},{"id":5751,"question":"سبب اختيار الإمام أحمد -رحمه الله- لدعاء الاستفتاح: سبحانك اللهم وبحمدك إلى آخره، مع أن هذا حديث منقطع كما قال المحدثون، ومن المعلوم أن الإمام أحمد ترك الأحاديث الصحيحة في ذلك؟","title":"سبب اختيار الإمام أحمد دعاء الاستفتاح «سبحانك اللهم وبحمدك..»","answer":"الجواب:  الحديث منقطع من طريق عمر، ولكنه جاء من طريق آخر، المنقطع من طريق عمر، ولكنه جاء من طريق عائشة، وأبي سعيد الخدري ..[وأبي هريرة].  وهو دعاء مختصر جدًا، ومحض في ذكر الله  فلهذا استحبه من استحب أن ... لكونه خالص بذكر الله ما فيه دعاء كله ذكر لله، وكله قائم لله؛ ولأنه مختصر ويحفظه الناس قليل.  ولهذا استحبه أحمد وغيره بغير إنكار للاستفتاحات الأخرى، فهو استفتاح موجز مختصر، جاء فيه عدة أحاديث، فلهذا استحبه جماعة من أهل العلم لاختصاره، وكونه محضًا للذكر، وتوحيد الله  وإذا استفتح بغيره مثل: اللهم باعد بيني وبين خطاياي اللهم رب جبرائيل وميكائيل..  إلى آخره فكله طيب، والأفضل أن يستفتح بهذا تارة، وهذا تارة، وهذا تارة حتى يكون جمع بين الاستفتاحات. وأسأل الله أن يوفق الجميع لمراضيه، وأن يوفقنا وإياكم للعلم النافع، والعمل الصالح، وأن يتقبل منا جميعًا، وصلى الله على نبينا محمد وعلى آله وصحبه.","link":"https://binbaz.org.sa/fatwas/1073/سبب-اختيار-الامام-احمد-دعاء-الاستفتاح-سبحانك-اللهم-وبحمدك","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk1_85.mp3","categories":["الأدعية والأذكار","التكبير والاستفتاح","الركوع والسجود"]},{"id":5767,"question":"سبب اختيار الإمام أحمد -رحمه الله- لدعاء الاستفتاح: سبحانك اللهم وبحمدك إلى آخره، مع أن هذا حديث منقطع كما قال المحدثون، ومن المعلوم أن الإمام أحمد ترك الأحاديث الصحيحة في ذلك؟","title":"سبب اختيار الإمام أحمد دعاء الاستفتاح «سبحانك اللهم وبحمدك..»","answer":"الجواب:  الحديث منقطع من طريق عمر، ولكنه جاء من طريق آخر، المنقطع من طريق عمر، ولكنه جاء من طريق عائشة، وأبي سعيد الخدري ..[وأبي هريرة].  وهو دعاء مختصر جدًا، ومحض في ذكر الله  فلهذا استحبه من استحب أن ... لكونه خالص بذكر الله ما فيه دعاء كله ذكر لله، وكله قائم لله؛ ولأنه مختصر ويحفظه الناس قليل.  ولهذا استحبه أحمد وغيره بغير إنكار للاستفتاحات الأخرى، فهو استفتاح موجز مختصر، جاء فيه عدة أحاديث، فلهذا استحبه جماعة من أهل العلم لاختصاره، وكونه محضًا للذكر، وتوحيد الله  وإذا استفتح بغيره مثل: اللهم باعد بيني وبين خطاياي اللهم رب جبرائيل وميكائيل..  إلى آخره فكله طيب، والأفضل أن يستفتح بهذا تارة، وهذا تارة، وهذا تارة حتى يكون جمع بين الاستفتاحات. وأسأل الله أن يوفق الجميع لمراضيه، وأن يوفقنا وإياكم للعلم النافع، والعمل الصالح، وأن يتقبل منا جميعًا، وصلى الله على نبينا محمد وعلى آله وصحبه.","link":"https://binbaz.org.sa/fatwas/1073/سبب-اختيار-الامام-احمد-دعاء-الاستفتاح-سبحانك-اللهم-وبحمدك","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk1_85.mp3","categories":["الأدعية والأذكار","التكبير والاستفتاح","الركوع والسجود"]},{"id":5829,"question":"هل يجب دعاء الاستفتاح عند الصلاة على الميت؟","title":"حكم دعاء الاستفتاح في صلاة الجنازة","answer":"الجواب: أما الصلاة على الميت فهي مخففة، فذكر العلماء أنه لا يستفتح فيها يبدأ بالتعوذ، والبسملة، ويقرأ الفاتحة، ولا يحتاج إلى استفتاح؛ لأنها صلاة مخففة، يطلب فيها تعجيل الميت، والإسراع به؛ فالأفضل أن لا يكون هناك استفتاح، هذا هو المنصوص عند أهل العلم. وبعض أهل العلم يرى فيها استفتاح، ولكن الأقرب -والله أعلم- عدم ذلك؛ لأنها صلاة مخففة، ليست ذات ركوع، ولا سجود.","link":"https://binbaz.org.sa/fatwas/1159/حكم-دعاء-الاستفتاح-في-صلاة-الجنازة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk1_158.mp3","categories":["التكبير والاستفتاح","سنن الصلاة"]},{"id":5899,"question":"إذا زار المؤمن المريض فما هو الدعاء الذي يدعو له فيه؟ وما هو دعاء الرسول ﷺ عندما زار المريض؟","title":"الدعاء الوارد في زيارة المريض","answer":"الجواب: لما زار المريض قال: طهور إن شاء الله، فليقل: طهور إن شاء الله، ويدعو له بالرحمة، والعافية، والشفاء، هذا المشروع.  إذا زاره يدعو له بالعافية، والشفاء، ويوصيه بتقوى الله، والصبر، ويذكره بأن الأمراض فيها الكفارة، والحط من الخطايا، تذكير بالله وحثه، ويدعو له بالشفاء، وأن يكون مرضه طهورًا، وتكفيرًا.","link":"https://binbaz.org.sa/fatwas/1246/الدعاء-الوارد-في-زيارة-المريض","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk1_242.mp3","categories":["التكبير والاستفتاح","الأدعية والأذكار"]},{"id":5907,"question":"إذا زار المؤمن المريض فما هو الدعاء الذي يدعو له فيه؟ وما هو دعاء الرسول ﷺ عندما زار المريض؟","title":"الدعاء الوارد في زيارة المريض","answer":"الجواب: لما زار المريض قال: طهور إن شاء الله، فليقل: طهور إن شاء الله، ويدعو له بالرحمة، والعافية، والشفاء، هذا المشروع.  إذا زاره يدعو له بالعافية، والشفاء، ويوصيه بتقوى الله، والصبر، ويذكره بأن الأمراض فيها الكفارة، والحط من الخطايا، تذكير بالله وحثه، ويدعو له بالشفاء، وأن يكون مرضه طهورًا، وتكفيرًا.","link":"https://binbaz.org.sa/fatwas/1246/الدعاء-الوارد-في-زيارة-المريض","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk1_242.mp3","categories":["التكبير والاستفتاح","الأدعية والأذكار"]},{"id":6035,"question":"ما حكم قراءة دعاء الاستفتاح في السنن الراتبة؟ وهل هو مستحب؟","title":"حكم دعاء الاستفتاح في صلاة النافلة","answer":"الجواب: مستحب الدعاء، مستحب في السنن، والفرائض.","link":"https://binbaz.org.sa/fatwas/1431/حكم-دعاء-الاستفتاح-في-صلاة-النافلة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk1_369.mp3","categories":["سنن الصلاة","التكبير والاستفتاح"]},{"id":6460,"question":"أناس من باكستان، وهؤلاء يرفعون أيديهم بعد الفريضة، فقال لهم الإمام هذه بدعة، ولكنهم قالوا: إن رفع الأيدي بعد صلاة الفريضة سنة في مذهب أبي حنيفة، ولم ينتهوا، واستمروا على ذلك، فما المخرج؟","title":"حكم رفع اليدين بعد الفريضة للدعاء","answer":"الجواب: ما من مذهب من مذاهب العلماء إلا وفيه بعض الأخطاء، كل عالم يخطئ ويصيب، ليس معصومًا، أبو حنيفة عالم من العلماء، والشافعي عالم من العلماء، ومالك عالم من العلماء، وأحمد بن حنبل عالم من العلماء، والأوزاعي عالم من العلماء، والثوري عالم من العلماء، وهكذا العلماء كثيرون من السلف، والخلف، كل واحد قد يقع له أخطاء، وأغلاط حسب اجتهاده؛ لأنه قد يفوتهم بعض العلم، قد يفوتهم بعض الأحاديث، فلا يقال: إن كل ما قاله عالم يكون حقًا، لا، أقوال العلماء تعرض على الكتاب والسنة، أقوالهم تعرض على كتاب الله، وعلى سنة رسوله محمد -عليه الصلاة والسلام- فما وافقهما، أو أحدهما؛ فهو الحق، وما خالف الكتاب، أوالسنة، أو خالفهما جميعًا؛ فهو باطل، وإن قاله عالم من العلماء. فرفع اليدين بعد الصلاة إن ثبت أن أبا حنفية قاله، إن ثبت؛ لأن ما كل يفعله أصحابه يكون من قوله، لكن إن ثبت أنه قاله، أو قاله بعض أئمة الحنفية؛ فإن هذا غلط، هذا يكون من الأغلاط التي وقعت له؛ لأن الرسول ﷺ وأصحابه ما فعلوا هذا، الرسول ﷺ ما كان إذا سلم في الظهر، أو في العصر، أو في المغرب، أو العشاء، والفجر رفع يديه، ويدعو ما كان يفعل هذا النبي ﷺ.  وفعل النبي محفوظ، نقله العلماء، نقله المحدثون، والرواة، وبينوا لنا أنه كان إذا سلم يقول: أستغفر الله ثلاثًا، اللهم أنت السلام، ومنك السلام، تباركت يا ذا الجلال والإكرام، ثم يلتفت إلى الناس، ويقول: لا إله إلا الله وحده لا شريك له، له الملك، وله الحمد، وهو على كل شيء قدير، لا حول ولا قوة إلا بالله، لا إله إلا الله، ولا نعبد إلا إياه، له النعمة، وله الفضل، وله الثناء الحسن، لا إله إلا الله مخلصين له الدين، ولو كره الكافرون، اللهم لا مانع لما أعطيت، ولا معطي لما منعت، ولا ينفع ذا الجد منك الجد، هكذا نقل الرواة، رواه الصحابة عن النبي ﷺ ولم يقولوا -وهم أعلم الناس بالسنة- ما قالوا: إنه يرفع يديه بعد السلام ... شيء رأوه إلا بينوه لنا، بينوا ما ترك، وبينوا ما فعل -عليه الصلاة والسلام- وهم الأمناء. فلم يذكروا أنه كان بعد السلام يرفع يديه، يدعو، ويدعو الناس معه، ولو كان ذلك واقعًا لما أهملوه، بل نقلوه، فتركه حجة، ونقله حجة، وما تركوا شيئًا حتى الصغير نقلوا أنه كان إذا جلس في التشهد يقبض أصابعه، ويشير بالسبابة، وربما حلق إبهامه، وأشار بالسبابة -عليه الصلاة والسلام- ونقلوا أنه كان إذا سلم التفت عن يمينه، وعن شماله.  ونقلوا أنه لما رأى الناس يشيرون بأيديهم عند السلام؛ نهاهم، وقال: لا تشيروا بأيديكم كأذناب خيل شمس وأمرهم أن يطمئنوا في صلاتهم، وبينوا أنه كان إذا جلس بين السجدتين وضع يده اليمنى على فخذه اليمنى، واليسرى على فخذه اليسرى، وربما وضعهما على ركبيته، كل شيء بينوه -رضي الله عنهم وأرضاهم- ولم يبينوا، ولم يقولوا: إنه كان يرفع يديه بعد ما يسلم من صلوات الفريضة، فعلى هذا يكون عمل الحنفية، أو من عمله منهم يكون خطأ، يكون مخالفًا للسنة، فلا ينبغي التعود عليه.  وهكذا ما جاء عن أبي حنيفة من عدم الرفع عند الركوع، وعند الرفع منه، وعند القيام من التشهد الأول، هذا ما يفعله الأحناف فاتتهم السنة في هذا، فلا يقتدى بهم في هذا، السنة حاكمة على الناس، النبي ﷺ كان يرفع يديه عند الإحرام هكذا، وعند الركوع هكذا، وعند الرفع من الركوع هكذا، يرفع يديه، وعند القيام من التشهد الأول للثالثة يرفع يديه، كما قاله أهل العلم، وبينه الصحابة، وثبت عن النبي ﷺ أنه كان يرفع يديه حيال منكبيه، وربما رفعهما حيال أذنيه في التحريمة، أول ما يكبر، وعند الركوع، وعند الرفع منه، وعند القيام للتشهد الأول.  وقد خفي هذا على الأحناف، وعلى بعض أهل العلم، فلم يقولوا بسنيته، ولكن علمه من علمه من أهل السنة، وعلمه العلماء، والعارفون بسنة النبي ﷺ وبينوا أنه مشروع، وأنه سنة، وإن خالف في هذا من خالف. القاعدة: أن ما يقوله بعض العلماء، أو يقوله كثير من العلماء، ويخالف فيه الآخرون الحاكم فيه كتاب الله، وسنة الرسول ﷺ لأن الله قال: فَإِنْ تَنَازَعْتُمْ فِي شَيْءٍ فَرُدُّوهُ إِلَى اللَّهِ وَالرَّسُولِ [النساء:59]، وقال سبحانه: وَمَا اخْتَلَفْتُمْ فِيهِ مِنْ شَيْءٍ فَحُكْمُهُ إِلَى اللَّهِ[الشورى:10].  فما تنازع فيه الناس يحكم فيه الله، ورسوله، يرد إلى القرآن، والسنة، فما وافقهما، أو أحدهما فهو الحق، وما خالفهما رد على قائله، وإن كان عظيمًا، وإن كان رجلًا عظيمًا، وإن كان كبيرًا، فالسنة، والحق أعظم من ذلك، وفق الله الجميع، وصلى الله وسلم على نبينا محمد ...","link":"https://binbaz.org.sa/fatwas/2183/حكم-رفع-اليدين-بعد-الفريضة-للدعاء","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk4_809.mp3","categories":["التكبير والاستفتاح","الأدعية والأذكار"]},{"id":6613,"question":"هل الدعاء مع رفع اليدين بعد الصلاة جائز؟","title":"حكم رفع اليدين بالدعاء عقب الصلوات","answer":"الجواب: ليس له أصل، ما كان النبي يرفع يديه بعد السلام -عليه الصلاة والسلام- بل كان يدعو بينه وبين نفسه -عليه الصلاة والسلام- فلا يرفع الناس أيديهم بعد السلام، لا بعد الظهر، ولا بعد العصر، ولا بعد المغرب، ولا بعد العشاء، ولا بعد الفجر، ما فعله النبي ﷺ ولا أصحابه -رضي الله عنهم- وأما الدعاء يدعو بينه وبين نفسه إذا دعا بعد الذكر؛ لا بأس. السؤال: وبعد السنة؟ الجواب: بعد السنة إذا فعله بعض الأحيان؛ لا بأس، بعض الأحيان، ما كان النبي يداوم على هذا الشيء -عليه الصلاة والسلام- فتارة، وتارة، إذا فعله تارة، وتارة؛ حسن، أو عرض له دعاء، فرفع يديه، ودعا.","link":"https://binbaz.org.sa/fatwas/2451/حكم-رفع-اليدين-بالدعاء-عقب-الصلوات","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk4_978.mp3","categories":["التكبير والاستفتاح","الأدعية والأذكار"]},{"id":6652,"question":"نرجو إيضاح قول الله تعالى عن الكهنة، ومن شابههم، الذين تركوا طريق الله، وذهبوا إلى الشياطين ليتعلموا منهما: مَا يُفَرِّقُونَ بِهِ بَيْنَ الْمَرْءِ وَزَوْجِهِ وَمَا هُمْ بِضَارِّينَ بِهِ مِنْ أَحَدٍ إِلَّا بِإِذْنِ اللَّهِ [البقرة:102] كيف يكون ذلك؟ وهل يحدث ذلك الضرر للمؤمنين، والفاسقين؟ وما هي طريق الوقاية من هذه الشرور، والأضرار حيث يروج كثير من الكهنة للعوام لقدرتهم على ذلك؟","title":"طرق الوقاية من شرور السحرة والكهنة","answer":"الجواب: قد يقع هذا الشيء، قد يسلكون هذه الطرق الخبيثة لخدمة الشياطين، وخدمة من تعاطى هذه الأمور، وصحبتهم لهم، وتعلمهم منهم من أنواع السحرة، والكهانة، والرمالة، والعرافة، وغير ذلك، يتعاطون هذه الأمور من أجل المال، ولأجل الاستحواذ على أموال الناس، أو حتى يعظمهم الناس، يقولون: يعرفون كذا، ويعرفون كذا هذا واقع، والله يبتلي عباده بالسراء، والضراء، ويبتلي عباده بالأشرار، والأخيار حتى يتبين الصادق من الكاذب، وحتى يتميز ولي الله، من عدو الله، وحتى يتميز من يعبد الله، ومن يسعى في سلامة دينه، ومن يحارب الكفر، والنفاق، والمعاصي، وحتى يتبين من هو ضعيف في ذلك، ناقص في ذلك، أو .. من الكسل، والضعف. فالله يميز الناس فيما يبتليهم به من السراء، والضراء، والشدة، والرخاء، وتسليط الأعداء، والجهلة، وأنواع الفساق، حتى يتبين أولياء الله من أعداء الله، والناصرون لدين الله من الضعفاء المخذلين، أو المخذولين إلى غير ذلك، هذا واقع. والتوقي من ذلك مشروع بحمد الله، توقي شرهم شرعه الله لعباده، توقى شرهم بما شرع الله من التعوذات، والأذكار الشرعية، والأدوية الشرعية، وقد أخبر النبي ﷺ: أن من نزل منزلًا، فقال: أعوذ بكلمات الله التامات من شر ما خلق؛ لم يضره شيء حتى يرتحل من منزله ذلك وقال: من قال أعوذ بكلمات الله التامات من شر ما خلق سبعًا؛ لم يضره شيء وقال: من قال: بسم الله الذي لا يضر مع اسمه شيء في الأرض، ولا في السماء، وهو السميع العليم -ثلاث مرات صباحًا- لم يضره شيء حتى يمسي، ومن قالها -ليلًا- لم يضره شيء حتى يصبح وقال: من قرأ آية الكرسي اللَّهُ لَا إِلَهَ إِلَّا هُوَ الْحَيُّ الْقَيُّومُ [البقرة:255] حين يضطجع؛ لم يضره شيء حتى يصبح.  وهذا من فضل الله  وهكذا قراءة قل هو الله أحد، والمعوذتين من أسباب السلامة من كل سوء، بعد الظهر، والعصر، والمغرب، والعشاء، والفجر، ويشرع تكرارها ثلاثاً بعد المغرب، والفجر، كل هذه من أسباب الوقاية. وكذلك الأذكار الشرعية: سبحان الله، والحمد لله، ولا إله إلا الله، والله أكبر، كلها من أسباب السلامة والعافية، وقراءة القرآن الكريم والعناية بأمر الله  وطاعته، وترك معاصيه، كلها من أسباب السلامة، وصح عن رسول الله ﷺ أنه قال: من قال لا إله إلا الله وحده لا شريك له، له الملك، وله الحمد وهو على كل شيء قدير -مائة مرة- كتب الله له مائة حسنة، ومحا عنه مائة سيئة، وكان في حرز من الشيطان، وكانت له عدل عشر رقاب يعتقها، وكان في حرز من الشيطان يومه ذلك حتى يمسي، ولم يأت أحد بأفضل مما جاء به إلا رجل عمل أكثر من عمله فالتعوذات، والأذكار الشرعية كلها من أسباب السلامة، والعافية.","link":"https://binbaz.org.sa/fatwas/2530/طرق-الوقاية-من-شرور-السحرة-والكهنة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk5_1025.mp3","categories":["التكبير والاستفتاح","الأدعية والأذكار"]},{"id":6667,"question":"هل يجوز إذا قال في الاستفتاح: وجهت وجهي للذي فطر السماوات، والأرض إلى آخر الآيات؟","title":"تنوع أدعية الاستفتاح في الصلاة","answer":"الجواب: كل ما صح عن النبي ﷺ يجوز، كل الاستفتاحات في الصلاة الثابتة عن النبي ﷺ يستفتح بها، بعد التحريمة بعد قوله: الله أكبر التكبيرة الأولى يستفتح، كل ما صح عن النبي ﷺ إذا قال: سبحانك اللهم وبحمدك، وتبارك اسمك، وتعالى جدك، ولا إله غيرك، وإذا دعا: اللهم باعد بيني وبين خطاياي كما باعدت بين المشرق والمغرب، اللهم نقني من خطاياي كما ينقى الثوب الأبيض من الدنس، اللهم اغسلني من خطاياي بالثلج، والماء، والبرد، ومنها وجهت وجهي للذي فطر السماوات، والأرض حنيفًا، وما أنا من المشركين، إلى آخره، ومنها أشياء أخرى. السؤال: ويقول: وأنا أول المسلمين؟ الجواب: وأنا من المسلمين.. الأول النبي ﷺ، أما أنت فمن المسلمين.","link":"https://binbaz.org.sa/fatwas/2552/تنوع-ادعية-الاستفتاح-في-الصلاة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk5_1047.mp3","categories":["التكبير والاستفتاح","سنن الصلاة"]},{"id":6800,"question":"ما حكم المداومة على رفع اليدين بالدعاء بعد النافلة؟ وما حكم من يعتقد أن رفع اليدين فضيلة؟","title":"حكم رفع اليدين بالدعاء بعد النافلة","answer":"الجواب: لا نعلم في هذا أصلًا، المداومة إذا فعلها بعض الأحيان؛ لأن رفع اليدين من أسباب الإجابة، فإذا فعله في بعض الأحيان، أو في دعاء عارض؛ هذا طيب، أما دائمًا دائمًا بعد كل صلاة ما نعرف له أصلًا، ولم يحفظ هذا عن النبي ﷺ ولا عن الصحابة فيما نعلم، لكن إذا فعله بعض الأحيان بعد صلاته، بعض الأحيان؛ فلا بأس، أما الفريضة فلا. السؤال: وإن اعتقد فضيلة بعد النافلة؟ الجواب: إذا كان لا يداوم عليها الأمر واسع. السؤال: لكن إذا كان يعتقدها فضيلة مثلًا بعد النافلة؟ الجواب: لا ما لها أصل، يعلم، يعلم أن هذا باطل، حديث إن ربكم حيي كريم يستحيي من عبده إذا رفع يديه أن يردهما صفرًا فرفع اليدين من أسباب الإجابة، لكن ما كان النبي ﷺ يواظب على هذا في صلاة النافلة، وإنما كان يفعله بعض الأحيان، وفعله ﷺ لما دعا على الصفا والمروة، رفع يديه، ولما دعا عند الجمرتين، الجمرة الأولى رفع يديه في أيام منى، وكذلك في الاستسقاء رفع يديه -عليه الصلاة والسلام- وفي عرفات، وفي مواضع أخرى رفع يديه ﷺ بالدعاء، أما بعد الفريضة مثل ما يفعل بعض الناس إذا سلموا دعا الإمام، والمأموم، ورفعوا أيديهم، هذا لا أصل له، بل بدعة. السؤال: بعد النافلة يجوز؟ الجواب: وبعد النافلة إذا فعله بعض الأحيان ما في بأس، لكن لا يكون مداومة. السؤال: وإذا داوم، ما يجوز؟ الجواب: يعلم، يعلم، لا ينبغي. السؤال: وإذا اعتقدوا فضيلة مثلًا؟ الجواب: يعلم، يعلم أن هذا لا ينبغي. السؤال: لكن يكون بدعة؟ الجواب: ينبغي تركه، الأفضل تركه، الأحوط ترك ذلك.","link":"https://binbaz.org.sa/fatwas/2677/حكم-رفع-اليدين-بالدعاء-بعد-النافلة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk5_1174.mp3","categories":["التكبير والاستفتاح","الأدعية والأذكار"]},{"id":6804,"question":"ما حكم المداومة على رفع اليدين بالدعاء بعد النافلة؟ وما حكم من يعتقد أن رفع اليدين فضيلة؟","title":"حكم رفع اليدين بالدعاء بعد النافلة","answer":"الجواب: لا نعلم في هذا أصلًا، المداومة إذا فعلها بعض الأحيان؛ لأن رفع اليدين من أسباب الإجابة، فإذا فعله في بعض الأحيان، أو في دعاء عارض؛ هذا طيب، أما دائمًا دائمًا بعد كل صلاة ما نعرف له أصلًا، ولم يحفظ هذا عن النبي ﷺ ولا عن الصحابة فيما نعلم، لكن إذا فعله بعض الأحيان بعد صلاته، بعض الأحيان؛ فلا بأس، أما الفريضة فلا. السؤال: وإن اعتقد فضيلة بعد النافلة؟ الجواب: إذا كان لا يداوم عليها الأمر واسع. السؤال: لكن إذا كان يعتقدها فضيلة مثلًا بعد النافلة؟ الجواب: لا ما لها أصل، يعلم، يعلم أن هذا باطل، حديث إن ربكم حيي كريم يستحيي من عبده إذا رفع يديه أن يردهما صفرًا فرفع اليدين من أسباب الإجابة، لكن ما كان النبي ﷺ يواظب على هذا في صلاة النافلة، وإنما كان يفعله بعض الأحيان، وفعله ﷺ لما دعا على الصفا والمروة، رفع يديه، ولما دعا عند الجمرتين، الجمرة الأولى رفع يديه في أيام منى، وكذلك في الاستسقاء رفع يديه -عليه الصلاة والسلام- وفي عرفات، وفي مواضع أخرى رفع يديه ﷺ بالدعاء، أما بعد الفريضة مثل ما يفعل بعض الناس إذا سلموا دعا الإمام، والمأموم، ورفعوا أيديهم، هذا لا أصل له، بل بدعة. السؤال: بعد النافلة يجوز؟ الجواب: وبعد النافلة إذا فعله بعض الأحيان ما في بأس، لكن لا يكون مداومة. السؤال: وإذا داوم، ما يجوز؟ الجواب: يعلم، يعلم، لا ينبغي. السؤال: وإذا اعتقدوا فضيلة مثلًا؟ الجواب: يعلم، يعلم أن هذا لا ينبغي. السؤال: لكن يكون بدعة؟ الجواب: ينبغي تركه، الأفضل تركه، الأحوط ترك ذلك.","link":"https://binbaz.org.sa/fatwas/2677/حكم-رفع-اليدين-بالدعاء-بعد-النافلة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk5_1174.mp3","categories":["التكبير والاستفتاح","الأدعية والأذكار"]},{"id":6823,"question":"ما حكم المداومة على رفع اليدين بالدعاء بعد النافلة؟ وما حكم من يعتقد أن رفع اليدين فضيلة؟","title":"حكم رفع اليدين بالدعاء بعد النافلة","answer":"الجواب: لا نعلم في هذا أصلًا، المداومة إذا فعلها بعض الأحيان؛ لأن رفع اليدين من أسباب الإجابة، فإذا فعله في بعض الأحيان، أو في دعاء عارض؛ هذا طيب، أما دائمًا دائمًا بعد كل صلاة ما نعرف له أصلًا، ولم يحفظ هذا عن النبي ﷺ ولا عن الصحابة فيما نعلم، لكن إذا فعله بعض الأحيان بعد صلاته، بعض الأحيان؛ فلا بأس، أما الفريضة فلا. السؤال: وإن اعتقد فضيلة بعد النافلة؟ الجواب: إذا كان لا يداوم عليها الأمر واسع. السؤال: لكن إذا كان يعتقدها فضيلة مثلًا بعد النافلة؟ الجواب: لا ما لها أصل، يعلم، يعلم أن هذا باطل، حديث إن ربكم حيي كريم يستحيي من عبده إذا رفع يديه أن يردهما صفرًا فرفع اليدين من أسباب الإجابة، لكن ما كان النبي ﷺ يواظب على هذا في صلاة النافلة، وإنما كان يفعله بعض الأحيان، وفعله ﷺ لما دعا على الصفا والمروة، رفع يديه، ولما دعا عند الجمرتين، الجمرة الأولى رفع يديه في أيام منى، وكذلك في الاستسقاء رفع يديه -عليه الصلاة والسلام- وفي عرفات، وفي مواضع أخرى رفع يديه ﷺ بالدعاء، أما بعد الفريضة مثل ما يفعل بعض الناس إذا سلموا دعا الإمام، والمأموم، ورفعوا أيديهم، هذا لا أصل له، بل بدعة. السؤال: بعد النافلة يجوز؟ الجواب: وبعد النافلة إذا فعله بعض الأحيان ما في بأس، لكن لا يكون مداومة. السؤال: وإذا داوم، ما يجوز؟ الجواب: يعلم، يعلم، لا ينبغي. السؤال: وإذا اعتقدوا فضيلة مثلًا؟ الجواب: يعلم، يعلم أن هذا لا ينبغي. السؤال: لكن يكون بدعة؟ الجواب: ينبغي تركه، الأفضل تركه، الأحوط ترك ذلك.","link":"https://binbaz.org.sa/fatwas/2677/حكم-رفع-اليدين-بالدعاء-بعد-النافلة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk5_1174.mp3","categories":["التكبير والاستفتاح","الأدعية والأذكار"]},{"id":6910,"question":"يسأل عن الدعاء الذي يقال عند الوضوء، بعض الناس ملتزم بدعاء ... عند غسل الرجل اليمنى يقول: اللهم ثبت قدمي اليمين على الصراط المستقيم، وعند اليسرى: اللهم ثبت قدمي الشمال عند صراط الرحمن، إلى غيره، وعند المضمضة، والاستنشاق، والوجه إلى غيره أدعيات مأثورة، فما ندري رأي سماحتكم في هذا، فهل هذا الدعاء صحيح؟","title":"ذكر الأدعية المشروعة عند الوضوء","answer":"الجواب: الوضوء مشروع فيه أمران: الأمر الأول: التسمية عند أوله، يسمي بالله عند أوله، عند غسل كفيه للوضوء، قبل أن يتمضمض، ويستنشق، أو عند المضمضة، والاستنشاق. ومشروع في حقه في آخره بعد الفراغ: أشهد ألا إله إلا الله وحده لا شريك له، وأشهد أن محمدًا عبده ورسوله، اللهم اجعلني من التوابين، واجعلني من المتطهرين سبحانك اللهم وبحمدك، أشهد أن لا إله إلا أنت، أستغفرك اللهم وأتوب إليك هذا المشروع بعد الوضوء.  وأما ما يقال عند غسل الوجه: اللهم بيض وجهي إلى آخره، وعند غسل اليدين: اللهم أعطني كتابي بيميني إلى آخره، وعند غسل القدمين: اللهم ثبت قدمي، هذا لا أصل له، وليس بمشروع.","link":"https://binbaz.org.sa/fatwas/2841/ذكر-الادعية-المشروعة-عند-الوضوء","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk6_1289.mp3","categories":["التكبير والاستفتاح","الأدعية والأذكار"]},{"id":6988,"question":"هل يجوز الذكر عند طبخ الطعام، وعند الأكل وهو جنب؟","title":"حكم الذكر وقراءة القرآن للجنب","answer":"الجواب: يسمي الله، ولو كان جنبًا، بس لا يقرأ القرآن حتى يغتسل، أما أن يقول: بسم الله، أو يقول: لا إله إلا الله، وسبحان الله، هذا طيب، ولو جنبًا، النبي ﷺ كان يذكر الله على كل أحيانه، يعني من الجنابة.","link":"https://binbaz.org.sa/fatwas/2891/حكم-الذكر-وقراءة-القران-للجنب","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk6_1339.mp3","categories":["التكبير والاستفتاح","الأدعية والأذكار"]},{"id":7029,"question":"إذا نسي الإنسان تكبيرة الإحرام، فهل يستمر  في الصلاة حتى ينتهي، ثم يعيدها، أو يقطعها، ثم يعيدها؟","title":"حكم من نسي تكبيرة الإحرام وتذكر أثناء الصلاة","answer":"الجواب:\n\nإذا شك هل كبر، أو ما كبر، يكبر في الحال، ويعمل لما أدرك بعد التكبير، إذا أعاد التكبيرة في الثانية من صلاة الإمام؛ اعتبر نفسه فاتته الأولى.\n\nوإذا أعاد التكبير في الثالثة اعتبر نفسه فاتته ركعتان، فيقضي ركعتين بعد الصلاة، هذا إذا كان ما هو موسوس، أما إذا كان موسوسًا -عنده وساوس- فلا يلتفت إلى هذا، يبني على ما تقدم ويعرف أنه كبر، والحمد لله.","link":"https://binbaz.org.sa/fatwas/3004/حكم-من-نسي-تكبيرة-الاحرام-وتذكر-اثناء-الصلاة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk6_1412.mp3","categories":["التكبير والاستفتاح","سنن الصلاة"]},{"id":7304,"question":"هل يجوز للإنسان أن يطلب من الصالحين أن يدعوا له، إذا كان يجوز؛ فإني أطلب من فضيلتكم والحاضرين بالدعاء لي بأن يسهل الله علي حفظ القرآن، وأن يفقهني في الدين، وأن يرزقني التأويل، وينفع بي المسلمين، مع الصلاح والإخلاص في القول والعمل، قولوا آمين؟","title":"حكم طلب الدعاء من الصالحين","answer":"الجواب: آمين، أصلحك الله، ويسر أمرك ورزقك حفظ القرآن الكريم، والعمل به، وهدانا وإياك وسائر المسلمين صراطه المستقيم، ولا بأس يجوز للمسلم أن يقول لأخيه: ادع الله لي يا أخي، ادع الله أن يهديني، ادع الله أن يغفر لي، لا بأس، هذا لا حرج فيه، لكن ما يدعى الأموات، إنما يدعى الأحياء. يقول للحي: يا أخي ادع الله لي أن الله يغفر لي، ادع الله لي أن ييسر لي زوجة صالحة، وذرية صالحة، لا بأس، أما الذهاب إلى الأموات، أو دعاؤهم من البعيد، يا سيدي البدوي، أو يا سيدي الحسين، أو يا فلان انصرني، أو اشفع لي، هذا منكر، هذا لا يجوز، هذا من الشرك الأكبر، نعوذ بالله.","link":"https://binbaz.org.sa/fatwas/3369/حكم-طلب-الدعاء-من-الصالحين","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk8_1687.mp3","categories":["التكبير والاستفتاح","الأدعية والأذكار"]},{"id":7330,"question":"لاحظنا على الحضور كلما سمعوا من سماحة الشيخ، قال: لا إله إلا الله، قالوا: لا إله إلا الله بصوت مرتفع بعض الشيء، ألا يكفي الاعتقاد بالقلب، وعدم رفع الصوت بصفة متكررة كلما ورد لفظ لا إله إلا الله، وهل هذا من البدع، أم لا؟","title":"حكم رفع الصوت جماعياً بالذكر من غير تواطؤ","answer":"الجواب: أما ما يفعل الصوفية بصوت جماعي يجتمعون ويرفعون الذكر بأصوات جماعية هذا من البدع، أما كون الإنسان يذكر الله وهذا يذكر الله، وإذا سمع من يذكر الله ذكر الله؛ لأنه انتبه، فذكره أخوه؛ فلا بأس، هذا أمر مشروع، يقول النبي ﷺ: سبق المفردون قالوا: يا رسول الله ما المفردون؟ قال: الذاكرون الله كثيرًا والذاكرات. ذكر الله مطلوب دائمًا قال تعالى: وَمَنْ يَعْشُ عَنْ ذِكْرِ الرَّحْمَنِ نُقَيِّضْ لَهُ شَيْطَانًا فَهُوَ لَهُ قَرِينٌ [الزخرف:36]، ويقول سبحانه: يَا أَيُّهَا الَّذِينَ آمَنُوا اذْكُرُوا اللَّهَ ذِكْرًا كَثِيرًا  ۝  وَسَبِّحُوهُ بُكْرَةً وَأَصِيلًا [الأحزاب:41-42].  فينبغي للمؤمن أن يكثر من ذكر الله في كل مكان، وإذا سمع الذكر من إخوانه انتبه، وذكر الله مثلما ذكر إخوانه هذا شيء مطلوب، وهكذا الصلاة على النبي ﷺ والسلام عليه ينبغي الإكثار من ذلك، لكن كونه ينظم تنظيمًا خاصًا بصوت جماعي هذا هو الذي ينكر، وهو بدعة، وهو ما يفعله الصوفيون، وفعله من قديم جماعة في عهد ابن مسعود في عهد الصحابة؛ فأنكر عليهم ابن مسعود رضي الله عنه وأرضاه.","link":"https://binbaz.org.sa/fatwas/3401/حكم-رفع-الصوت-جماعيا-بالذكر-من-غير-تواطو","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk8_1714.mp3","categories":["التكبير والاستفتاح","الأدعية والأذكار"]},{"id":7338,"question":"سألت الله، وألححت بدعائي، وأواظب على الصلاة، والصيام والزكاة، وحججت بيت الله، وكلما أحاوله وبدون جدوى أطلب منه طلبًا عاديًا حتى الآن لم أتمكن منه منذ ثمان سنوات، رغم أني سعيت وبحثت ما قد يفوق طاقتي، وكل طلبي هو الزواج، وحتى الآن لم أوفق لدرجة أني أتصور أني مخطئ مع الله في شيء -والله أعلم-.","title":"الإلحاح في الدعاء وعدم اليأس","answer":"الجواب:  لا تيأس يا ولدي، لا تيأس -جزاك الله خيرًا- لا تيأس، عليك بالطلب والدعاء، وعليك بأخذ الأسباب، سل ربك أن الله يسهل لك زوجة صالحة، واعمل بالأسباب، توصي الناس الذين تعرفهم يلتمسون لك زوجة، وتعمل الأسباب لتحصيل المال، وتحاسب نفسك من جهة المعاصي، قد تكون حرمت بسبب معصية أنت مقيم عليها، فحاسب نفسك، قال -جل وعلا-: وَمَا أَصَابَكُمْ مِنْ مُصِيبَةٍ فَبِمَا كَسَبَتْ أَيْدِيكُمْ وَيَعْفُو عَنْ كَثِيرٍ [الشورى:30].  بل قال بعض السلف: إنه دعا الله أربعين عامًا في حاجة، فلم تحصل له إلا بعد أربعين عامًا، فربك أعلم وأحكم، قد يؤجلها لحكمة بالغة، قد يكون في هذا مصلحتك حتى يسهل الله لك توبة صادقة من أعمال سيئة، أو يحصل لك زوجة صالحة ما بعد حصل وقتها، إلى غير ذلك، يقول النبي ﷺ: يستجاب لأحدكم ما لم يعجل، فيقول دعوت دعوت فلم أره يستجاب لي فيستحسر عند ذلك، ويدع الدعاء.  فالواجب أن الإنسان لا يستحسر، بل يستمر في الدعاء ويحسن ظنه بربه، ويقول -عليه الصلاة والسلام- أيضًا: ما من عبد يدعو الله بدعوة ليس فيها إثم ولا قطيعة رحم إلا أعطاه الله بها إحدى ثلاث: إما أن تعجل له دعوته، وإما أن تدخر له في الآخرة، وإما أن يصرف عنه من الشر مثل ذلك قالوا: يا رسول الله إذًا نكثر، قال: الله أكثر فأنت استمر في الدعاء، واجتهد، وخذ بالأسباب، والتمس المرأة، والتمس أسباب المهر، ونحوه؛ حتى تدرك ذلك -إن شاء الله- ولا تيأس ولا تقنط، واعلم أن ما أصابك من شيء؛ فمن نفسك، لا بد أن تحاسبها أيضًا، تتوب إلى الله -جل وعلا- تنظر في أعمالك، تستقيم على طاعة ربك.","link":"https://binbaz.org.sa/fatwas/3415/الالحاح-في-الدعاء-وعدم-الياس","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk8_1727.mp3","categories":["التكبير والاستفتاح","الأدعية والأذكار"]},{"id":8597,"question":"من أدرك الإمام راكعاً فهل تلزمه تكبيرة، أو تكبيرتان: تكبيرة الإحرام وتكبيرة الركوع؟","title":"حكم تكبيرة الانتقال لمن أدرك الإمام راكعاً","answer":"الجواب: نعم، إذا أدرك الإمام راكعاً فإنه يكبر أولاً وهو واقف تكبيرة الإحرام ثم يكبر حين ينحني للركوع، هذا هو الذي ينبغي وهذا هو الأصل، الأصل أن يكبر تكبيرتين الأولى: وهي تكبيرة الإحرام وهي فرض عند الجميع لا بد منها، والثانية فرض عند بعض أهل العلم وهي تكبيرة الركوع، وذهب الأكثرون إلى أنها سنة، ولكن ذهب الإمام أحمد رحمه الله وجماعة من السلف والخلف إلى أنها فريضة؛ لأن النبي ﷺ كبر وأمر بالتكبير وقال: صلوا كما رأيتموني أصلي في الركوع والسجود فدل ذلك على وجوب التكبيرات تكبيرات النقل تأسياً به ﷺ وتنفيذاً لأمره.\nأما تكبيرة الإحرام وهي الأولى، فهذه فريضة عند الجميع، لا يدخل الصلاة إلا بها، لو دخل في الصلاة بالنية ولم يكبر لم تنعقد صلاته، فلا بد من التكبير في أول الصلاة، وهي التكبيرة التي يقال لها: تكبيرة الإحرام، وهي المذكورة في قوله ﷺ: مفتاح الصلاة الطهور، وتحريمها التكبير، وتحليلها التسليم يعني: التكبير الأول.\nلكن إذا جاء والإمام راكع فقد يضيق الوقت فإن ترك تكبيرة الركوع صح عند جمع من أهل العلم، لضيق الوقت، ولكن إذا أتى بهما فهو الأحوط وفيه خروج من الخلاف، فينبغي له أن يأتي بهما على الأصل، يكبر وهو واقف التكبيرة الأولى وهي تكبيرة الإحرام ثم يكبر الثانية عند انحنائه وانخفاضه للركوع، متى تيسر ذلك فهذا هو الأحوط والأولى، ومتى ترك الثانية للضيق أجزأته الركعة والحمد لله في أصح قولي أهل العلم. نعم.\nالمقدم: جزاكم الله خيرا.","link":"https://binbaz.org.sa/fatwas/6712/حكم-تكبيرة-الانتقال-لمن-ادرك-الامام-راكعا","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_129/12902.mp3","categories":["سنن الصلاة","التكبير والاستفتاح"]},{"id":9139,"question":"الرسالة التالية وصلت إلى البرنامج من المستمع عبدالعزيز حسين إبراهيم سوداني يعمل في المملكة في بريد رابغ، يقول في رسالته: بسم الله الرحمن الرحيم وما توفيقي إلا بالله، السؤال الأول يقول فيه: إنني سمعت كثيراً من المصلين يقولون بعد تكبيرة الإحرام مباشرة أدعية مثل: وجهت وجهي إلى فاطر السماء والأرض، أو إلى الكعبة الشريفة، نويت أن أصلي صلاة العصر أو العشاء، ثم بعد ذلك يقول: الله أكبر ويدخل في الصلاة، فما رأيكم في هذا، أفيدونا أفادكم الله؟","title":"حكم دعاء الاستفتاح والجهر بالنية قبل الدخول في الصلاة","answer":"الجواب: السنة للمؤمن إذا قام إلى الصلاة أن يستحضر عظمة ربه وأن هذه الصلاة لها شأن عظيم، وأن الخشوع فيها مطلوب، كما قال الله : قَدْ أَفْلَحَ الْمُؤْمِنُونَ ۝ الَّذِينَ هُمْ فِي صَلاتِهِمْ خَاشِعُونَ [المؤمنون:1-2]، فيقوم بهذه النية بنية الدخول فيها، وإذا كبر الإمام قال بعده: الله أكبر، وإن كان منفرداً لمرض منعه من الجماعة أو في النافلة فإنه يكبر يقول: (الله أكبر) أول ما يبدأ الصلاة، ولا يشرع له أن يقول: نويت أن أصلي كذا وكذا، هذا شيء لا أصل له، والصواب أنه غير مشروع بل هو بدعة؛ لأن الرسول ﷺ ما كان يقول عند البدء بالصلاة: نويت أن أصلي كذا وكذا، وما كان أصحابه يقولون ذلك، ولا الأئمة الأربعة، ولا غيرهم من أهل العلم المعروفين من أئمة السلف الصالح. فالسنة للمؤمن والمؤمنة أن يبدأا الصلاة بقوله: الله أكبر، ولا يأتي بقوله: نويت أن أصلي الظهر كذا والعصر كذا.. الفجر كذا.. الجمعة كذا، هذا لا أصل له، ولكن ينوي في قلبه أنه قائم للصلاة المعينة الظهر أو العصر أو المغرب أو العشاء ويكفي، القلب هو محل النية.\nأما وجهت وجهي فهذا يقوله بعد الدخول، هذا يسمى: الاستفتاح، إذا كبر يقول الاستفتاح المشروع الذي كان يفعله النبي ﷺ، وقد صح عنه ﷺ أنواع من الاستفتاحات أخصرها وأوجزها: سبحانك اللهم وبحمدك وتبارك اسمك وتعالى جدك ولا إله غيرك، يقول هذا بعد التكبير، يقوله الرجل والمرأة في الفرض والنفل: سبحانك اللهم وبحمدك وتبارك اسمك وتعالى جدك ولا إله غيرك ومعنى: تعالى جدك يعني: عظمتك، جد الله: عظمته سبحانه وتعالى، ولا إله غيرك يعني: لا معبود بحق في الأرض ولا في السماء سواك يا ربنا، فهو المعبود بالحق سبحانه وتعالى، وما عبده الناس من دون الله من قبور وأصحاب قبور أو أنبياء أو صالحين أو كواكب أو صنم أو شجر كله باطل، أما المعبود بالحق فهو الله وحده سبحانه وتعالى، وهذا معنى: لا إله غيرك، أي: لا معبود بحق سواك، قال الله تعالى: ذَلِكَ بِأَنَّ اللَّهَ هُوَ الْحَقُّ وَأَنَّ مَا يَدْعُونَ مِنْ دُونِهِ هُوَ الْبَاطِلُ [الحج:62].\nويشرع استفتاحاً آخر كان الرسول يستعمله عليه الصلاة والسلام وهو ثابت عنه: اللهم باعد بيني وبين خطاياي كما باعدت بين المشرق والمغرب، اللهم نقني من خطاياي كما ينقى الثوب الأبيض من الدنس، اللهم اغسلني من خطاياي بالثلج والماء والبرد، هذا أيضاً كان يستعمله النبي ﷺ وهو ثابت عنه في الصحيحين، فإذا فعله الإنسان قبل أن يقرأ: اللهم باعد بيني وبين خطاياي كما باعدت بين المشرق والمغرب، اللهم نقني من خطاياي كما ينقى الثوب الأبيض من الدنس، اللهم اغسلني من خطاياي بالثلج والماء والبرد هذا مستحب وليس بواجب قبل أن يقرأ وبعد أن يكبر، وهناك نوع ثالث من الاستفتاح يقول: وجهت وجهي للذي فطر السموات والأرض حنيفاً وما أنا من المشركين، إن صلاتي ونسكي ومحياي ومماتي لله رب العالمين لا شريك له، وبذلك أمرت وأنا من المسلمين، اللهم أنت الملك لا إله إلا أنت، أنت ربي وأنا عبدك، ظلمت نفسي واعترفت بذنبي فاغفر لي ذنوبي جميعاً إنه لا يغفر الذنوب إلا أنت، واهدني لأحسن الأخلاق لا يهدي لأحسنها إلا أنت، واصرف عني سيئها لا يصرف عني سيئها إلا أنت، لبيك وسعديك والخير كله في يديك، والشر ليس إليك، أنا بك وإليك، تباركت وتعاليت، أستغفرك وأتوب إليك، هذا نوع من الاستفتاح وهو صحيح ثابت، كان في الغالب يستعمله بالليل عليه الصلاة والسلام، وفي التطوع وإذا استعمله الإنسان في الفريضة فلا بأس؛ لأن شأنهما واحد إلا ما خصه الدليل، ولكنه طويل ليس كل واحد يحفظه، فالأول أخصر وأيسر على العامة من الرجال والنساء: سبحانك اللهم وبحمدك، وتبارك اسمك، وتعالى جدك ولا إله غيرك، ثم يقول: أعوذ بالله من الشيطان الرجيم، بسم الله الرحمن الرحيم، ويقرأ الحمد، ثم ما تيسر معها بعد ذلك، هذا هو المشروع. نعم.\nالمقدم: أحسن الله إليكم.","link":"https://binbaz.org.sa/fatwas/7299/حكم-دعاء-الاستفتاح-والجهر-بالنية-قبل-الدخول-في-الصلاة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_230/23002.mp3","categories":["سنن الصلاة","التكبير والاستفتاح"]},{"id":9659,"question":"وما حكم دعاء الاستفتاح والتعوذ من عذاب جهنم وعذاب القبر وفتنة المحيا والممات والمسيح الدجال؟","title":"حكم دعاء الاستفتاح والتعوذ من الأربع بعد التشهد","answer":"الجواب: كله سنة.. كله سنة.. الاستفتاح بـ سبحانك اللهم وبحمدك وتبارك اسمك وتعالى جدك ولا إله غيرك أواللهم باعد بيني وبين خطاياي الحديث، أو غيرهما من الاستفتاحات كله سنة ومستحب وليس بلازم إنما هو مستحب، إذا كبر تكبيرة الإحرام قبل أن يقرأ يقول: سبحانك الله وبحمدك وتبارك اسمك وتعالى جدك ولا إله غيرك في الفرض والنفل جميعاً. أو يأتي باستفتاح آخر مما صح عن النبي ﷺ، ومن ذلك ما صح عنه ﷺ أنه كان يقول -أول ما يكبر، يسكت هنيهة- ويقول: اللهم باعد بيني وبين خطاياي كما باعدت بين المشرق والمغرب، اللهم نقني من خطاياي كما ينقى الثوب الأبيض من الدنس، اللهم اغسلني من خطاياي بالثلج والماء والبرد هذا أصح ما ورد عنه عليه الصلاة والسلام.\nوإن استفتح بغير ذلك من الاستفتاحات الصحيحة فهو سنة، واحد منها يكفي، وأقصرها: سبحانك اللهم وبحمدك، وتبارك اسمك، وتعالى جدك، ولا إله غيرك هذا أقصرها، يستطيع حفظه كل أحد من الناس، ثم بعد هذا يقول: أعوذ بالله من الشيطان الرجيم، بِسْمِ اللَّهِ الْرَّحمَنِ الْرَّحَيمِ [الفاتحة:1] ويقرأ الفاتحة.\nوأما التعوذ من عذاب جهنم ومن عذاب القبر إلى آخره فهذا سنة مؤكدة في آخر الصلاة قبل أن يسلم، يقول: «أعوذ بالله من عذاب جهنم ومن عذاب القبر، ومن فتنة المحيا والممات، ومن فتنة المسيح الدجال» سنة مؤكدة، كان النبي ﷺ يفعلها ويأمر بها.\nويستحب له الدعاء بغير هذا، مثل: اللهم أعني على ذكرك وشكرك وحسن عبادتك اللهم اغفر لي ولوالدي اللهم إني ظلمت نفسي ظلماً كثيراً ولا يغفر الذنوب إلا أنت، فاغفر لي مغفرة من عندك وارحمني إنك أنت الغفور الرحيم اللهم اغفر لي ما قدمت وما أخرت وما أسررت وما أعلنت وما أسرفت، وما أنت أعلم به مني، أنت المقدم وأنت المؤخر لا إله إلا أنت كل هذا صح عن النبي ﷺ.","link":"https://binbaz.org.sa/fatwas/7832/حكم-دعاء-الاستفتاح-والتعوذ-من-الاربع-بعد-التشهد","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_251/25114.mp3","categories":["التكبير والاستفتاح","سنن الصلاة"]},{"id":9707,"question":"هذه سائلة أم أسامة مقيمة في جدة تقول: عندما أبدأ بالصلاة، وقبل أن أكبر، أستعيذ بالله من الشيطان الرجيم ثم البسملة ثم أكبر، وأعيد هذه الاستعاذة والبسملة بعد التكبير ودعاء الاستفتاح، فهل يصح مني هذا أم أن هذه الطريقة غير صحيحة؟","title":"حكم الإتيان بالاستعاذة والبسملة قبل تكبيرة الإحرام","answer":"الجواب: السنة أن تكتفي بالاستعاذة والتسمية بعد التكبير، بعد الاستفتاح عند بدء القراءة.\nأما الإتيان بالاستعاذة والتسمية أول الصلاة ما عليه دليل، لكن إذا كبرت وأتيت بالاستفتاح: (سبحانك اللهم وبحمدك وتبارك اسمك وتعالى جدك ولا إله غيرك) أو بأي استفتاح آخر من الاستفتاحات الصحيحة، بعدها تقولي: أعوذ بالله من الشيطان الرجيم، بسم الله الرحمن الرحيم، ثم تقرئين الفاتحة، هذا المشروع، أما تأتين بها قبل التكبير ما لها أصل. نعم.\nالمقدم: جزاكم الله خيراً.","link":"https://binbaz.org.sa/fatwas/7857/حكم-الاتيان-بالاستعاذة-والبسملة-قبل-تكبيرة-الاحرام","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_272/27206.mp3","categories":["التكبير والاستفتاح","النية في الصلاة"]},{"id":10250,"question":"تقول أختنا: ذكر النووي في كتاب الأذكار: أنه يستحب أن لا يجمع بين جميع الأدعية الواردة عن رسول الله صلى الله عليه وسلم في دعاء الاستفتاح أو في الركوع فما هو رأي سماحتكم؟","title":"حكم الجمع بين أكثر من دعاء وارد في الاستفتاح","answer":"الجواب: السنة أن ينوع في الاستفتاح، ما كان النبي يجمعها عليه الصلاة والسلام في الاستفتاح تارةً يستفتح بما جاء في حديث عمر: سبحانك اللهم وبحمدك وتبارك اسمك وتعالى جدك ولا إله غيرك وتارةً بما جاء في حديث أبي هريرة: اللهم باعد بيني وبين خطاياي كما باعدت بين المشرق والمغرب، اللهم نقني من خطاياي كما ينقى الثوب الأبيض من الدنس، اللهم اغسلني من خطاياي بالثلج والماء والبرد وهو في الصحيحين، وتارة يستفتح بما جاء في حديث عائشة: اللهم رب جبريل وميكائيل وإسرافيل فاطر السماء والأرض عالم الغيب والشهادة أنت تحكم بين عبادك فيما كانوا يختلفون، اهدني لما اختلف فيه من الحق، إنك تهدي من تشاء إلى صراط مستقيم.\nوهكذا في بعض الأحيان يستفتح بما في حديث علي: وجهت وجهي للذي فطر السموات والأرض حنيفًا وما أنا من المشركين.. إلى آخره، هو حديث طويل رواه مسلم في الصحيح، أو بما جاء في حديث ابن عباس في البخاري ورواه مسلم أيضًا وهو حديث طويل: اللهم لك الحمد أنت قيوم السموات والأرض ومن فيهن ولك الحمد أنت ملك السموات والأرض ومن فيهن ولك الحمد أنت نور السموات والأرض ومن فيهن... إلى آخر الحديث الطويل، فالمؤمن هكذا ..... والمؤمنة كذلك، يعني تارةً يستفتح بهذا وتارةً يستفتح بهذا، وإن استمر على واحد فلا بأس، وأصحها ما رواه أبو هريرة  عن النبي ﷺ أنه ..كان يستفتح إذا كبر في الصلاة للفريضة يقول: اللهم باعد بيني وبين خطاياي كما باعدت بين المشرق والمغرب، اللهم نقني من خطاياي كما ينقى الثوب الأبيض من الدنس، اللهم اغسلني من خطاياي بالثلج والماء والبرد خرجه البخاري ومسلم في الصحيحين.\nأما الأذكار في الركوع والسجود فإنه يأتي منها بما تيسر، يشرع له أن يأتي بما تيسر، لكن يخص (سبحان ربي العظيم) في الركوع و (سبحان ربي الأعلى) في السجود، فيقول في الركوع: (سبحان ربي العظيم سبحان ربي العظيم) فإذا كررها ثلاثًا فهو أفضل والواجب مرة، وذهب الجمهور إلى أنها مستحبة فقط، ولكن ذهب جمع من أهل العلم إلى وجوب هذا الذكر: (سبحان ربي العظيم) في الركوع و (سبحان ربي الأعلى) في السجود؛ لأن الرسول حافظ عليها عليه الصلاة والسلام، وقال: صلوا كما رأيتموني أصلي وروي عنه عليه الصلاة والسلام أنه قال لما نزل قوله تعالى: فَسَبِّحْ بِاسْمِ رَبِّكَ الْعَظِيمِ [الحاقة:52] قال: اجعلوها في ركوعكم، ولما نزل قوله تعالى: سَبِّحِ اسْمَ رَبِّكَ الأَعْلَى [الأعلى:1] قال: اجعلوها في سجودكم.\nفينبغي للمؤمن والمؤمنة المحافظة على ذلك، (سبحان ربي العظيم) في الركوع و (سبحان ربي الأعلى) في السجود، والأفضل أن يكرر ذلك ثلاثًا وإن كرر أكثر فهو أفضل، ويستحب مع هذا أن يقول: (سبحانك اللهم ربنا وبحمدك، اللهم اغفر لي) في الركوع والسجود، تقول عائشة رضي الله عنها: كان النبي ﷺ يكثر أن يقول في ركوعه وسجوده: سبحانك اللهم ربنا وبحمدك اللهم اغفر لي ويستحب أن يقول: (سبوح قدوس رب الملائكة والروح)، كان يقوله النبي أيضًا في الركوع والسجود عليه الصلاة والسلام، فإن أتى بما تيسر من هذا كان هذا أفضل، وإن اقتصر على البعض فلا بأس، وإن جمع الجميع فلا بأس، لكن لا يدع (سبحان ربي العظيم) في الركوع، ولا يدع (سبحان ربي الأعلى) في السجود ولو مرة، ويستحب له أن يكثر في السجود من الدعاء، يستحب له الإكثار من الدعاء في السجود؛ لقوله عليه الصلاة والسلام: أما الركوع فعظموا فيه الرب، وأما السجود فاجتهدوا في الدعاء فقمن أن يستجاب لكم ... فحري أن يستجاب لكم، رواه مسلم في صحيحه، وقال أيضا عليه الصلاة والسلام: أقرب ما يكون العبد من ربه وهو ساجد فأكثروا الدعاء رواه مسلم أيضًا.\nفالسنة الإكثار من الدعاء في السجود، مع قول: (سبحان ربي الأعلى، سبحان ربي الأعلى)، مع قول: (سبحانك اللهم ربنا وبحمدك اللهم اغفر لي)، وهكذا بين السجدتين يقول: (رب اغفر لي رب اغفر لي اللهم اغفر لي وارحمني واهدني وارزقني وعافني) يكرر ذلك، وإن دعا بزيادة (اللهم اغفر لي ولوالدي وللمسلمين) فلا بأس كله دعاء.\nوالسنة أن يطيل هذا الركن وهو الجلوس بين السجدتين كان النبي ﷺ يطيله حتى يقول القائل: قد نسي، وهكذا بعد الركوع السنة أن يطيل الاعتدال بعد الركوع، قال أنس : كان النبي ﷺ يطيل هذا الاعتدال بعد الركوع وبين السجدتين حتى يقول القائل: قد نسي بعض الناس ينقر هذا الركن ولا يعطيه حقه بل يعجل وهذا لا يجوز، بل الواجب الطمأنينة في جميع الصلاة، في الركوع والسجود والاعتدال بعد الركوع والجلوس بين السجدتين، يجب الاعتدال في هذا والطمأنينة.\nأما ذكر الاعتدال بعد الركوع فإنه لم يرد ما يدل على التكرار لكن يأتي به إذا تيسر كله: (ربنا ولك الحمد حمدًا كثيرًا طيبًا مباركًا فيه ملء السموات وملء الأرض وملء ما بينهما وملء ما شئت من شيء بعد أهل الثناء والمجد أحق ما قال العبد وكلنا لك عبد اللهم لا مانع لما أعطيت ولا معطي لما منعت ولا ينفع ذا الجد منك الجد)، هذا هو الكمال وإلا اقتصر على قوله: (ربنا ولك الحمد) أو (اللهم ربنا لك الحمد) أجزأه الإمام والمأموم والمنفرد، لكن إذا كمل كان أفضل، وإن اقتصر على قوله: (ربنا ولك الحمد ملء السموات وملء الأرض وملء ما بينهما وملء ما ما شئت من شيء بعد) فلا بأس أيضًا، ولكن الواجب: (ربنا ولك الحمد) أو (اللهم ربنا لك الحمد)، لأن الرسول عليه السلام قال: إذا قال الإمام: سمع الله لمن حمده، فقولوا: ربنا ولك الحمد فدل ذلك أن هذا هو الواجب والباقي مستحب وكمال.\nوهكذا الواجب بين السجدتين يقول: (رب اغفر لي)، فإن النبي ﷺ كان يحافظ على ذلك: (رب اغفر لي) والواجب مرة كالتسبيح في الركوع والسجود، ولكن إذا كرر ذلك ثلاثًا أو أكثر كان أفضل، (رب اغفر لي رب اغفر لي) لما يجلس بين السجدتين، وإذا زاد (اللهم اغفر لي وارحمني واهدني وارزقني وعافني واجبرني) كان أفضل. نعم.\nالمقدم: جزاكم الله خيرًا ونفع بعلمكم.","link":"https://binbaz.org.sa/fatwas/8421/حكم-الجمع-بين-اكثر-من-دعاء-وارد-في-الاستفتاح","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_336/33603.mp3","categories":["الأدعية والأذكار","التكبير والاستفتاح","الركوع والسجود"]},{"id":10266,"question":"أولى رسائل هذه الحلقة رسالة المستمعة (ع. م. الخطيب ) من الضفة الغربية بفلسطين بعثت بهذه الرسالة وضمنتها عددًا من الأسئلة، عرضنا بعض أسئلتها في حلقات مضت وفي هذه الحلقة تسأل وتقول: أرى النووي يقول في تفسيره ما معناه: إنه يستحب مد التكبيرة في الصلاة عند الانتقال من ركن إلى ركن حتى لا يخلو جزء من صلاته من الذكر، فما الحكم فيمن يستمر في التكبير عند الانتقال بدون أن يمد فيأتي بثلاث تكبيرات أو أربع بين الركعتين أو بين الركنين؟","title":"صفة تكبيرات الانتقال في الصلاة","answer":"الجواب: بسم الله الرحمن الرحيم، الحمد لله، وصلى الله وسلم على رسول الله، وعلى آله وأصحابه ومن اهتدى بهداه.\nأما بعد: فأمور الدين يتلقاها العلماء والمسلمون عن الأدلة من الكتاب والسنة لا من قول فلان وفلان، إلا إذا وافق قوله كتابًا أو سنة، فالسنة في التكبير عدم التمطيط بل يكبر عند انتقاله كما يكبر في أول الإحرام من غير تمطيط، قد يأتي بتكبير معتدل: (الله أكبر، الله أكبر) عند الإحرام عند الركوع عند السجود، عند الرفع من السجود، أما تمطيط لا، غير مشروع، كونه يقول: (الله أكبر) يمدها بقدر انحطاطه لا، ليس هذا بمشروع، ولكن التكبير جزم، والسلام جزم، فيقول: (الله أكبر) مدة معتدلة طبيعية ليس فيها تكلف، وهكذا: (سمع الله لمن حمده، ربنا ولك الحمد)، وهكذا: (السلام عليكم ورحمة الله، السلام عليكم ورحمة الله)، لا يقل: (السلام عليكم ورحمة الله)، ما له حاجة هذا الجزم: (السلام عليكم ورحمة الله)، وهكذا: (الله أكبر)، ولا يكرر واحدة، تكبيرة واحدة عند الإحرام، الموسوسون يكررون التكبير، هذه وسوسة لا تجوز، ولكن يكبر واحدة عند الإحرام، الله أكبر، وعند الركوع واحدة، وعند السجود واحدة، وعند الرفع من السجود واحدة، وعند السجود الثاني واحدة، وعند الرفع منه واحدة هكذا، هذا ما شرعه الله، هذا هو المشروع، لكن مدًا طبيعيًا ليس فيه تكلف، هذا هو المشروع للرجل والمرأة جميعًا وللإمام والمنفرد والمأموم. نعم.\nالمقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/8437/صفة-تكبيرات-الانتقال-في-الصلاة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_337/33706.mp3","categories":["التكبير والاستفتاح","النية في الصلاة"]},{"id":10383,"question":"بعد هذا ننتقل إلى رسالة وصلت إلى البرنامج من اليمن -صنعاء- وباعثها المستمع صادق نعمان يسأل ويقول: إذا سجدت أيهما أضع أولًا: الكفين أم الركبتين؟","title":"ما السنة عند الهويِّ إلى السجود في الصلاة؟","answer":"الجواب: الأفضل الركبتان، تضع الركبتين ثم اليدين ثم الجبهة والأنف، هذا هو السنة، تبدأ بالركبتين؛ لأن الرسول ﷺ: نهى عن البروك كما يبرك البعير، البعير يبدأ بيديه، فأنت تبدأ بركبتيك لأنها برجليك، وفي الحديث الآخر: كان النبي ﷺ إذا سجد وضع ركبتيه قبل يديه وهو حديث حسن لا بأس به، يتفق مع أحاديث البروك.\nفالمقصود أن السنة والمشروع البداءة بالرجلين: الركبتين ثم يديك ثم جبهتك وأنفك، وعند الرفع ترفع رأسك ثم يديك ثم ركبتيك، هذا هو الأصح. نعم.","link":"https://binbaz.org.sa/fatwas/8555/ما-السنة-عند-الهوي-الى-السجود-في-الصلاة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_280/28008.mp3","categories":["الأدعية والأذكار","التكبير والاستفتاح","الركوع والسجود"]},{"id":10628,"question":"سماحة الشيخ! أجبتم المستمع السابق عن دعاء الاستفتاح، وأخونا السواط يسأل عن تفسير دعاء الاستفتاح؟","title":"شرح أدعية الاستفتاح","answer":"الجواب: كل دعاء له تفسير، حديث قوله: سبحانك اللهم وبحمدك وتبارك اسمك وتعالى جدك ولا إله غيرك معناه: تنزيه الله عن كل ما لا يليق به سبحانك اللهم وبحمدك يعني: معناه: أنزهك يا ربي! عن كل شيء لا يليق بك؛ من الشرك والصفات الناقصة، كالنعاس والنوم والعجز ونحو ذلك، فهو سبحانه منزه عن كل نقص وعن كل عيب، وهو الكامل في ذاته وأسمائه وصفاته وأفعاله .\nوتبارك اسمك: يعني: بلغ في البركة النهاية، كل البركة عنده .\nوتعالى جدك يعني: عظمتك، الجد: العظمة في حق الله، يعني: تعالت عظمتك يا ربنا!\nولا إله غيرك معناه: لا معبود بحق سواك يا الله! هو المعبود بالحق .\nوأما دعاء الاستفتاح: اللهم باعد بيني وبين خطاياي كما باعدت بين المشرق والمغرب، اللهم نقني من خطاياي كما ينقى الثوب الأبيض من الدنس، اللهم اغسلني من خطاياي بالثلج والماء والبرد فهذا معناه: طلب السلامة من الذنوب، يطلب ربه أن ينقيه من الذنوب والخطايا، وأن يباعد بينه وبينها؛ حتى تكون توبته صادقة كاملة ليس معها نقص ولا ذنب، فإنه إذا باعد بينه وبين خطاياه ونقاه منها وطهره منها، صار نقياً من الذنوب كامل الإيمان والتقوى.\nوأما معنى: اللهم رب جبريل وميكائيل و إسرافيل ، فاطر السماوات والأرض عالم الغيب والشهادة، أنت تحكم بين عبادك فيما كانوا فيه يختلفون، اهدني لما اختلف فيه من الحق بإذنك معناه: طلب الهداية، توسل بأنه رب جبرائيل وميكائيل وإسرافيل ، وجبرائيل وميكائيل وإسرافيل ثلاثة من الملائكة، وهم مقدمو الملائكة وأفضل الملائكة، جبرائيل: الذي يأتي بالوحي للأنبياء، وميكائيل: الموكل بالقطر والمطر، وإسرافيل: الموكل بالنفخ في الصور يوم القيامة وإعادة الأرواح إلى الأجساد، هؤلاء هم مقدمو الملائكة، توسل بربوبية الله لهم اللهم رب جبرائيل ... إلى آخره.\nفأنت بهذا تتوسل إلى الله بأنه رب هؤلاء الملائكة ، وتتوسل إليه بأنه فاطر السماوات والأرض، يعني: خالق السماوات والأرض، وأنه عالم الغيب والشهادة، تتوسل بهذا أنه العالم بكل شيء، العالم بكل شيء وفاطر المخلوقات والموجد لها ، وأنه رب كل شيء ومليكه جل وعلا، وأنه الحاكم بين عباده في الدنيا والآخرة، هو الحاكم بينهم في الدنيا بشرعه، وفي الآخرة بحكمه العدل  ثم بهذا تطلب منه أن يهديك لما وقع فيه الاختلاف، تقول: اهدني لما اختلف فيه من الحق بإذنك تسأله أن يهديك للصواب والحق الذي وقع فيه الخلاف بين الناس، وتتوسل إليه بأنه الذي يهدي من يشاء إلى صراط مستقيم، فأنت تسأله بهذه الوسائل أن يهديك إلى الحق والصواب. نعم.\nالمقدم: جزاكم الله خيراً.","link":"https://binbaz.org.sa/fatwas/8804/شرح-ادعية-الاستفتاح","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_328/32806.mp3","categories":["التكبير والاستفتاح"]},{"id":10674,"question":"هل تغير موضع السجود في الصلاة يؤثر عليها؟","title":"حكم تغيير موضع السجود في الصلاة الواحدة","answer":"الجواب: لا نعلم في هذا شيئاً إذا سجد تقدم أو تأخر قليل عن موضع السجود لا يضر، المقصود أنه يتحرى السجود في المحل الذي لا يؤذيه، فإن كان فيه شيء أزاله مسحة واحدة بيده، المقصود أن كونه يتقدم قليلاً أو يتأخر قليلاً في السجود يتحرى ما يناسب جبهته وأنفه لا يضره، لكن يكون معتدل في السجود، بعض الناس ........... هذا غير مشروع، إنما يعتدل ويعتمد على كفيه، ويرفع ذراعيه، ويجافي عضديه عن جنبيه، وبطنه عن فخذيه، وفخذيه عن ساقيه، يكون معتدل في السجود، مستقيم في السجود، فإذا قدم جبهته قليلاً أو أخرها قليلاً تحرى المحل الذي يريحه هذا ما يضره. هذا نعم.","link":"https://binbaz.org.sa/fatwas/8873/حكم-تغيير-موضع-السجود-في-الصلاة-الواحدة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_330/33023.mp3","categories":["الأدعية والأذكار","التكبير والاستفتاح","الركوع والسجود"]},{"id":11155,"question":"السائلة علوة من أبها تقول في سؤالها الأول: هل دعاء الاستفتاح واجب على المسلم أن يقرأه في النوافل، وفي صلاة التراويح؟ وهل تبطل الصلاة بتركه، وجهونا بهذا؟","title":"حكم دعاء الاستفتاح في الفرائض والنوافل","answer":"الجواب:  دعاء الاستفتاح ليس بواجب، سنة، مستحب، لا تبطل الصلاة بتركه، لا في النافلة، ولا في الفريضة، ولكنه مستحب، يقول: سبحانك اللهم وبحمدك، وتبارك اسمك، وتعالى جدك، ولا إله غيرك بعد الإحرام، بعد التكبيرة الأولى، وقبل أن يقرأ، أو يأتي بأنواع الاستفتاحات الأخرى مثل: اللهم باعد بيني وبين خطاياي كما باعدت بين المشرق والمغرب، اللهم نقني من خطاياي كما ينقى الثوب الأبيض من الدنس، اللهم اغسلني من خطاياي بالثلج والماء والبرد ... وغيرها مما صح عن النبي ﷺ لكن أسهلها وأحضرها: سبحانك اللهم وبحمدك، وتبارك اسمك، وتعالى جدك، ولا إله غيرك نعم.","link":"https://binbaz.org.sa/fatwas/9328/حكم-دعاء-الاستفتاح-في-الفراىض-والنوافل","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_290/29017.mp3","categories":["التكبير والاستفتاح","النية في الصلاة"]},{"id":11866,"question":"في هيئة السجود هل النزول على اليدين، أم على الركبتين؟","title":"كيفية الهوي للسجود في الصلاة","answer":"الجواب:  السنة للقادر النزول على الركبتين، كما في حديث وائل وغيره، وهو المراد في حديث أبي هريرة: لا يبرك أحدكم كما يبرك البعير هذا الصواب؛ لأن بروك البعير يبرك على يديه، ونحن منهيون أن نبرك على أيدينا، نبرك على ركبنا التي في الرجلين، هذا هو السنة، وهذا هو الصحيح، وهو قول الجمهور من أهل العلم، أن السنة البروك على ركبتيه، لا على يديه؛ خلافًا للبعير، هذا إذا كان قادرًا، أما إذا كان عاجزًا لكبر السن، أو لمرض؛ فإنه يبرك على يديه، لا بأس لأجل العجز. المقدم: جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/10050/كيفية-الهوي-للسجود-في-الصلاة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_397/39713.mp3","categories":["الأدعية والأذكار","التكبير والاستفتاح","الركوع والسجود"]},{"id":12121,"question":"هل يجوز الدعاء من القرآن الكريم في سجود الصلاة فرضًا كان، أم نافلة؟","title":"حكم الدعاء من القرآن في السجود","answer":"الجواب: نعم. يجوز الدعاء بدعوات القرآن إذا كان ذلك على سبيل الدعاء، لا على سبيل القراءة، فقد ثبت عن رسول الله -عليه الصلاة والسلام- أنه نهى عن القراءة في الركوع والسجود، لكن إذا دعا مثل: رَبَّنَا لا تُزِغْ قُلُوبَنَا بَعْدَ إِذْ هَدَيْتَنَا وَهَبْ لَنَا مِنْ لَدُنْكَ رَحْمَةً إِنَّكَ أَنْتَ الْوَهَّابُ [آل عمران:8]، أو قال: رَبَّنَا آتِنَا فِي الدُّنْيَا حَسَنَةً وَفِي الآخِرَةِ حَسَنَةً وَقِنَا عَذَابَ النَّارِ [البقرة:201]، هذا لا بأس على سبيل الدعاء، لا على سبيل القراءة، فدعوات القرآن إذا قيلت في السجود أو في آخر التحيات على سبيل الدعاء والضراعة إلى الله لا على سبيل القراءة لا حرج في ذلك، نعم. المقدم: جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/10306/حكم-الدعاء-من-القران-في-السجود","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_438/43806.mp3","categories":["الأدعية والأذكار","التكبير والاستفتاح","الركوع والسجود"]},{"id":12668,"question":"له سؤال آخر يقول فيه: ما مقادير الأقوال والأفعال الواجبة والمستحبة في الصلاة؟","title":"مقدار ما يجب في الركوع والسجود من الأذكار","answer":"الجواب:  الواجب في السجود: سبحان ربي الأعلى مرة، وفي الركوع: سبحان ربي العظيم مرة، والزائد مستحب، يكرر ويأتي بقول: سبحانك اللهم ربنا وبحمدك، اللهم اغفر لي، هذا مستحب. وهكذا قوله: سبوح قدوس رب الملائكة والروح في الركوع والسجود، هذا مستحب، كذلك الدعاء في السجود مستحب، وهكذا بين السجدتين يقول: رب اغفر لي، الواجب مرة، وإذا كرر كان أفضل، وإذا زاد: \"اللهم اغفر لي وارحمني واهدني واجبرني وارزقني وعافني\" كان أفضل مع الطمأنينة في الجميع، وعدم العجلة، وهكذا إذا رفع من الركوع إن كان إمامًا، أو منفردًا، يقول: \"سمع الله لمن حمده، ربنا ولك الحمد\" أو \"اللهم ربنا ولك الحمد\" أو \"ربنا لك الحمد\" كله جاء، هذا الواجب. وإن كان مأمومًا إذا رفع يقول: \"ربنا ولك الحمد\" أو \"ربنا لك الحمد\" أو \"اللهم ربنا لك الحمد\" أو \"اللهم ربنا ولك الحمد\" كله حق، هذا الواجب والزائد مستحب (حمدًا كثيرًا ... ) إلى آخره مستحب، وهو الأفضل أن يكمل، نعم. المقدم: جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/10878/مقدار-ما-يجب-في-الركوع-والسجود-من-الاذكار","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_416/41602.mp3","categories":["الأدعية والأذكار","التكبير والاستفتاح","الركوع والسجود"]},{"id":12843,"question":"يسأل عن مشروعية الدعاء أثناء السجود، هل هو جائز؟","title":"حكم الدعاء أثناء السجود","answer":"الجواب:  سنة الدعاء في السجود، سنة، الدعاء في السجود أمر به النبي ﷺ في صحيح مسلم عن أبي هريرة  عن النبي ﷺ أنه قال: أقرب ما يكون العبد من ربه وهو ساجد؛ فأكثروا الدعاء وهذا حديث صحيح، يدل على شرعية الدعاء في السجود، ولهذا قال ﷺ: أقرب ما يكون العبد من ربه وهو ساجد؛ فأكثروا الدعاء وفي حديث ابن عباس عند مسلم -رحمه الله- في الصحيح يقول ﷺ: أما الركوع فعظموا فيه الرب، وأما السجود فاجتهدوا في الدعاء، فقمن أن يستجاب لكم يعني: حري أن يستجاب لكم، فهذان الحديثان الصحيحان يدلان على شرعية الدعاء في السجود. وثبت عنه ﷺ: أنه كان يدعو في سجوده ويقول: اللهم اغفر لي ذنبي كله، دقه وجله، وأوله وآخره، وعلانيته وسره فقد ثبت هذا من فعله، ومن قوله، عليه الصلاة والسلام. فيشرع للمؤمن أن يدعو في السجود في الفرض والنفل جميعًا؛ لأن الرسول أمر بهذا، وفعله -عليه الصلاة والسلام-نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/11057/حكم-الدعاء-اثناء-السجود","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_464/46409.mp3","categories":["الأدعية والأذكار","التكبير والاستفتاح","الركوع والسجود"]},{"id":12950,"question":"تقول السائلة: سمعت من بعض الناس بأنه لا يجوز السجود على القماش الأسود، هل هذا صحيح؟","title":"حكم السجود على القماش الأسود","answer":"الجواب:  ليس بصحيح، يجوز السجود على القماش الأسود والأحمر والأصفر، لكن يكون ما فيه نقوش، الأحسن ألا يكون فيه نقوش تشغل المصلي، إذا كان فيه نقوش؛ تركه أولى، سواء أصفر وإلا أحمر وإلا أسود وإلا غيره، أما إذا كان سادة؛ فهو الأفضل، سواء كان أسود أو أحمر أو أخضر أو غير ذلك، نعم.","link":"https://binbaz.org.sa/fatwas/11166/حكم-السجود-على-القماش-الاسود","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_502/50209.mp3","categories":["الأدعية والأذكار","التكبير والاستفتاح","الركوع والسجود"]},{"id":13125,"question":"إذا أقيمت الصلاة، هل هناك دعاء يدعو به المصلي قبل تكبيرة الإحرام؟","title":"هل يشرع دعاء معين قبل تكبيرة الإحرام؟","answer":"الجواب:  لا نعلم شيئًا في ذلك، وقد سئل أحمد عن هذا؛ فأجاب بأنه لا يعلم شيئًا في هذا، فإذا دعا بشيء فلا بأس، لكن ليس هناك شيء معروف سنة، فإذا دعا بشيء: اللهم اغفر لي، أو اللهم ارحمني، أو أنجني من النار، أو تقبل مني ما فيه شيء، لا نعلم فيه شيئًا، لكن ليس في هذا شيء خاص يستحب، نعم. المقدم: جزاكم الله خيرًا، هناك حديث أذكر معناه سماحة الشيخ: الدعاء لا يرد بين الأذان والإقامة هل هذا يدخل في هذا الباب؟ الشيخ: نعم هذا حديث لا بأس به، هذا بين الأذان والإقامة قبل الإقامة. المقدم: جزاكم الله ....، قبل الإقامة؟ الشيخ: الدعاء بين الأذان والإقامة ترجى إجابته، ثبت هذا من حديث أنس عن النبي ﷺ أنه قال: الدعاء بين الأذان والإقامة لا يرد فينبغي الإكثار من الدعاء بين الأذان والإقامة، يعني: قبل الإقامة، وبعد الأذان. نعم. المقدم: جزاكم الله خيرًا، بعض الناس يفهمه أنه بعد الإقامة. الشيخ: لا، بين الأذان والإقامة. المقدم: بين الأذان.. الشيخ: يعني: قبل الإقامة، وبعد الأذان. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/11349/هل-يشرع-دعاء-معين-قبل-تكبيرة-الاحرام","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_474/47403.mp3","categories":["التكبير والاستفتاح","النية في الصلاة"]},{"id":13197,"question":"يقول السائل في آخر أسئلته: ما حكم وضع اليدين بعد الرفع من الركوع مثل: السدل، أم القبض، وجهونا جزاكم الله خيرًا؟","title":"أفضلية الضم بعد الرفع من الركوع","answer":"الجواب:  الأفضل القبض بعد الرفع من الركوع، الأفضل القبض؛ لأنه ثبت عن النبي ﷺ ما يدل على ذلك من حديث وائل بن حجر، ومن حديث قبيصة بن هلب الطائي عن أبيه \"أن النبي ﷺ كان يضع يديه على صدره حال قيامه في الصلاة\" وهذا القيام يشمل ما بعد الركوع، وما قبل الركوع؛ لأنه قيام، فيضع يديه على صدره، هذا هو الأفضل، نعم. المقدم: جزاكم الله خيرًا سماحة الشيخ.","link":"https://binbaz.org.sa/fatwas/11466/افضلية-الضم-بعد-الرفع-من-الركوع","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_512/51204.mp3","categories":["الأدعية والأذكار","التكبير والاستفتاح","الركوع والسجود"]},{"id":13228,"question":"نختم هذا اللقاء بسؤال السائل محمد علي يقول: هل يجب على المصلي أن يكشف عن جبينه عند السجود في الصلاة، مثلًا: الطاقية، أو الغترة، أو العمامة، أو يلزمه ذلك؟","title":"هل يجب على المصلي أن يكشف جبينه عند السجود؟","answer":"الجواب:  أفضل وإلا لا يلزمه، لو سجد على الطاقية، أو على العمامة، أو على غيرهما لا بأس، ولكن كونه يحسرها حتى تباشر جبهته المصلى يكون هذا أفضل وأولى، أن يباشر بجبهته وأنفه المصلى، نعم.","link":"https://binbaz.org.sa/fatwas/11508/هل-يجب-على-المصلي-ان-يكشف-جبينه-عند-السجود","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_512/51221.mp3","categories":["الأدعية والأذكار","التكبير والاستفتاح","الركوع والسجود"]},{"id":13705,"question":"يقول هذا السائل: إذا صلى شخص، هل صحيح بأنه إذا دخل المأموم والإمام يقرأ أي سورة بعدما قرأ الفاتحة، والمأموم لم يقرأ دعاء الاستفتاح، فهل في ذلك شيء؟ وهل تبطل الصلاة في مثل هذه الحالة؟","title":"حكم قراءة دعاء الاستفتاح للمسبوق","answer":"الجواب: إذا دخل المأموم والإمام يقرأ بعد الفاتحة فإنه يقرأ الفاتحة فقط، ولا يقرأ الاستفتاح؛ لأن الاستفتاح نافلة، وهو مأمورٌ بالإنصات، لكن قراءة الفاتحة لازمة، فيقرأ الفاتحة، ثم ينصت لإمامه، وأما الاستفتاح فلا حاجة إلى قراءته؛ لأنه مأمور بالإنصات، وهو نافلة ليس بواجب الاستفتاح، ولكن يشرع في الفاتحة بينه وبين نفسه حتى يقرأها، ثم ينصت لإمامه. نعم. المقدم: بارك الله فيكم.","link":"https://binbaz.org.sa/fatwas/12076/حكم-قراءة-دعاء-الاستفتاح-للمسبوق","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_535/53506.mp3","categories":["التكبير والاستفتاح","النية في الصلاة"]},{"id":13805,"question":"أولى رسائل هذه الحلقة رسالة وصلت إلى البرنامج من المستمع (ح. م. م) الشائع أخونا سؤاله مطول بعض الشيء ملخصه: أنه لاحظ أن كثيرًا من الناس لا يسجدون على الأعضاء السبعة كاملة ويرجو من سماحة الشيخ تنبيههم جزاكم الله خيرا.","title":"حكم ترك السجود على أحد الأعضاء السبعة","answer":"الجواب: بسم الله الرحمن الرحيم، الحمد لله، وصلى الله وسلم على رسول الله وعلى آله وأصحابه ومن اهتدى بهداه.\nأما بعد: فالواجب على كل مسلم ومسلمة السجود على الأعضاء السبعة؛ وهي الوجه والجبهة والأنف والكفان والركبتان وأطراف القدمين، لما ثبت عن النبي ﷺ أنه قال: أمرت أن أسجد على سبعة أعظم على الجبهة -وأشار بيده إلى أنفه- والكفين والركبتين وأطراف القدمين. فالواجب على جميع المسلمين من الذكور والإناث أن يعنوا بهذا وأن يحرصوا على ذلك، وهذا السجود على هذه الأعضاء فرض ركن لابد منه، فلا يجوز التساهل في ذلك، بل يجب على المصلي ذكرًا كان أو أنثى أن يسجد على هذه السبعة في الفرض والنفل جميعًا، وإذا تركها عمدًا بطلت صلاته، وإن تركها سهوًا فإن أمكنه أن يأتي بها في الحال أتى بها في الحال، وإن لم يذكرها إلا بعدما قام إلى الركعة الأخرى أتى بركعة بدالها بعد ذلك إذا كمل يأتي بركعة بدل ما ترك من الأعضاء، وتقوم الركعة الثانية مقام الأولى مقام التي قبلها التي ترك منها العضو أو العضوين.\nوالحاصل أنه لابد من السجود على هذه الأعضاء السبعة ولا يجوز تركها ولا ترك شيء منها لا في الفرض ولا في النفل. نعم.\nويسجد للسهو أيضًا إذا كان تركها سهوًا بأن يرفع يده ولا سجد عليها، أو إحدى رجليه لم يسجد عليها ساهيًا ثم تذكر بعد ذلك بعدما اشتغل بالركعة التي بعدها فإنه يأتي بركعة بدلاً منها ويسجد للسهو سجدتين قبل أن يسلم ثم يسلم. نعم.\nالجواب: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/12171/حكم-ترك-السجود-على-احد-الاعضاء-السبعة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_602/60201.mp3","categories":["الأدعية والأذكار","التكبير والاستفتاح","الركوع والسجود"]},{"id":13831,"question":"يقول: كيف تكون وضع الرجلين عند السجود؟ هل هي مضمومة؟ أم متفرقة؟","title":"كيفية وضع الرجلين عند السجود في الصلاة","answer":"الجواب: مفرقة، السنة أن يفرقهما كما يفرق يديه إذا سجد، وهكذا يفرق رجليه إذا سجد، أما ما يروى: أنه ﷺ كان ساجدًا وكعبه ملتصق بالكعب الآخر فهذا فيه نظر، والظاهر أنه شاذ مخالف للأحاديث الصحيحة رواه الحاكم وجماعة، والمحفوظ: أنه ﷺ كان يقيم قدميه كل واحدة منفردة عن الأخرى. نعم.\nالمقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/12201/كيفية-وضع-الرجلين-عند-السجود-في-الصلاة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_537/53711.mp3","categories":["الأدعية والأذكار","التكبير والاستفتاح","الركوع والسجود"]},{"id":13834,"question":"يقول: كيف تكون وضع الرجلين عند السجود؟ هل هي مضمومة؟ أم متفرقة؟","title":"كيفية وضع الرجلين عند السجود في الصلاة","answer":"الجواب: مفرقة، السنة أن يفرقهما كما يفرق يديه إذا سجد، وهكذا يفرق رجليه إذا سجد، أما ما يروى: أنه ﷺ كان ساجدًا وكعبه ملتصق بالكعب الآخر فهذا فيه نظر، والظاهر أنه شاذ مخالف للأحاديث الصحيحة رواه الحاكم وجماعة، والمحفوظ: أنه ﷺ كان يقيم قدميه كل واحدة منفردة عن الأخرى. نعم.\nالمقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/12201/كيفية-وضع-الرجلين-عند-السجود-في-الصلاة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_537/53711.mp3","categories":["الأدعية والأذكار","التكبير والاستفتاح","الركوع والسجود"]},{"id":13894,"question":"سماحة الشيخ! في سؤاله الثاني يقول: هل الصحيح أن ينزل المصلي بيديه قبل ركبتيه، أم أن الأصح ما نراه من نزول المصلين بركبتيهم إلى السجود؟","title":"حكم البدء بالركبتين قبل اليدين عند السجود","answer":"الجواب: هذا هو السنة، كان النبي ﷺ يهوي إلى سجوده على ركبتيه، ويقول: لا يبرك أحدكم كما يبرك البعير، والبعير يبرك على يديه يقدم يديه، فالسنة لمن عنده قوة أن ينزل على ركبتيه، وتكون يداه بعد ذلك، ثم وجهه، هذا السنة، الركبتان ثم اليدان ثم الوجه، هذا إذا كان يقوى على ذلك، وهذا هو الأفضل، فإن أصابه ما يمنعه من ذلك من كبر سن أو مرض سجد على يديه والحمد لله. نعم.\nالمقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/12265/حكم-البدء-بالركبتين-قبل-اليدين-عند-السجود","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_538/53807.mp3","categories":["الأدعية والأذكار","التكبير والاستفتاح","الركوع والسجود"]},{"id":14103,"question":"يسأل أخونا ويقول: إذا دخلت المسجد ووجدت الإمام راكعًا أو ساجدًا، هل لي أن أستفتح الصلاة في هذه الحالة؟ أم يكفيني استفتاح الإمام؟","title":"من أدرك الإمام راكعًا هل يقرأ دعاء الاستفتاح؟","answer":"الجواب: إذا وجدته راكعًا أو ساجدًا فكبر وادخل معه وليس هناك حاجة إلى الاستفتاح، كبر وادخل معه في الركوع، كبر وادخل معه في السجود والحمد لله، وليس هناك حاجة إلا إذا كان قائمًا تكبر وأنت قائم وتستفتح ثم تقرأ الفاتحة. نعم.","link":"https://binbaz.org.sa/fatwas/12529/من-ادرك-الامام-راكعا-هل-يقرا-دعاء-الاستفتاح","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_614/61407.mp3","categories":["التكبير والاستفتاح","النية في الصلاة"]},{"id":14104,"question":"يسأل أخونا ويقول: إذا دخلت المسجد ووجدت الإمام راكعًا أو ساجدًا، هل لي أن أستفتح الصلاة في هذه الحالة؟ أم يكفيني استفتاح الإمام؟","title":"من أدرك الإمام راكعًا هل يقرأ دعاء الاستفتاح؟","answer":"الجواب: إذا وجدته راكعًا أو ساجدًا فكبر وادخل معه وليس هناك حاجة إلى الاستفتاح، كبر وادخل معه في الركوع، كبر وادخل معه في السجود والحمد لله، وليس هناك حاجة إلا إذا كان قائمًا تكبر وأنت قائم وتستفتح ثم تقرأ الفاتحة. نعم.","link":"https://binbaz.org.sa/fatwas/12529/من-ادرك-الامام-راكعا-هل-يقرا-دعاء-الاستفتاح","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_614/61407.mp3","categories":["التكبير والاستفتاح","النية في الصلاة"]},{"id":14175,"question":"يقول يا سماحة الشيخ هذا السائل في هذا  أقول في سجودي أحيانًا الصلاة الإبراهيمية المعروفة بالكامل في صلاة النفل، فهل يجوز ذلك مع الدعاء، اللهم آت محمد..","title":"حكم قول الصلاة الإبراهيمية و(اللهم آت محمدًا الوسيلة...) في السجود","answer":"الجواب: هذا من أسباب الإجابة، يحمد الله ويثني عليه ويصلي على النبي ﷺ ولو في السجود ولو في آخر الصلاة، يثني على الله ويصلي على النبي ﷺ ثم يدعو؛ لأن هذا من أسباب الإجابة، كما أنه في التحيات يقرأ التحيات ثم يصلي على النبي ﷺ ثم يدعو؛ لأن التحيات ثناء على الله، ثم بعدها الصلاة على النبي ﷺ ثم يدعو، فإذا أحب يدعو في السجود ثم يتهجد بالليل، يحمد الله ويثني عليه ويصلي على النبي ﷺ ويدعو؛ لأن هذا من أسباب الإجابة.\nالمقدم: يقول يا سماحة الشيخ عبد العزيز: هل يجوز أن أضيف هذا الدعاء : اللهم آت محمدًا الوسيلة والفضيلة والدرجة العالية الرفيعة وذلك في الصلاة الإبراهيمية؟\nالشيخ: لا، المشروع الصلاة الإبراهيمية التي بينها لأصحابه لما سألوه: «كيف نصلي عليك؟ قال: قولوا: اللهم صل على محمد وعلى آل محمد كما صليت على إبراهيم وعلى آل إبراهيم إنك حميد مجيد، اللهم بارك على محمد وعلى آل محمد كما باركت على إبراهيم وعلى آل إبراهيم إنك حميد مجيد وجاءت بألفاظ أخرى وكل ما صح عن النبي ﷺ في هذا يفعل، بعد قراءة التحيات بعد الشهادتين، أما اللهم آت محمداً الوسيلة هذه بعد الأذان هذه تقال بعد الأذان. نعم.\nالمقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/12618/حكم-قول-الصلاة-الابراهيمية-واللهم-ات-محمدا-الوسيلة-في-السجود","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_547/54710.mp3","categories":["الأدعية والأذكار","التكبير والاستفتاح","الركوع والسجود"]},{"id":14368,"question":"يقول السائل: هل هناك علامة تظهر في جبهة الفرد تسمى علامة الصلاة؟","title":"هل في الجبهة علامة تسمى علامة الصلاة؟","answer":"الجواب: قد تقع لبعض الناس، قد يبين على جبهته بعض الشيء؛ لكثرة سجوده، قد يقع هذا، نعم.","link":"https://binbaz.org.sa/fatwas/12849/هل-في-الجبهة-علامة-تسمى-علامة-الصلاة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_551/55110.mp3","categories":["الأدعية والأذكار","التكبير والاستفتاح","الركوع والسجود"]},{"id":14543,"question":"هل تجوز الصلاة بدون قراءة دعاء الاستفتاح في أول الصلاة؟","title":"حكم دعاء الاستفتاح في أول الصلاة","answer":"الجواب: الاستفتاح سنة مستحب، ولو صلى ولم يستفتح صلاته صحيحة عند جميع العلماء، الاستفتاح سنة مستحبة، والاستفتاح هو أن يقول بعد التكبيرة الأولى: سبحانك اللهم وبحمدك، وتبارك اسمك، وتعالى جدك، ولا إله غيرك هذا يسمى الاستفتاح، بعد التكبيرة الأولى تكبيرة الإحرام، وإن استفتح بغير هذا مما صح عن النبي ﷺ فهو حسن، مثل: اللهم باعد بيني وبين خطاياي، كما باعدت بين المشرق والمغرب، اللهم نقني من خطاياي كما ينقى الثوب الأبيض من الدنس، اللهم اغسلني من خطاياي بالثلج والماء والبرد هذا صحيح أيضًا، رواه البخاري ومسلم في الصحيحين، كان يستفتح به النبي ﷺ في الصلوات، وهناك استفتاحات أخرى صحت عنه -عليه الصلاة والسلام-. والحاصل: أنه إذا استفتح بشيء مما صح عن النبي ﷺ قبل القراءة فهو مستحب وسنة، ولو ترك ذلك فلا حرج عليه، فصلاته صحيحة.","link":"https://binbaz.org.sa/fatwas/13041/حكم-دعاء-الاستفتاح-في-اول-الصلاة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_489/48904.mp3","categories":["التكبير والاستفتاح","سنن الصلاة"]},{"id":14842,"question":"من الأوصاف التي وصف بها المنافقون أنهم إذا سجدوا نقروا، وإذا ركعوا ربضوا، فكيف يكون الربوض لتحاشي ذلك ومخالفتهم؟","title":"معنى الربض في السجود","answer":"الجواب: المعروف عن المنافقين النقر، الذي ينقرها يعني: يعجل فيها في ركوعه وسجوده، لا يذكر الله فيها إلا قليلًا.  أما الربض في كلام بعض العلماء فالربض كونه يسجد سجود ما هو معتدل، مثل ربض البهيمة، يسجد سجود ما هو معتدل.  فالسنة أن يعتدل في سجوده، يسجد على يديه وركبتيه، وأطراف قدميه وجبهته وأنفه رافعًا بطنه عن فخذيه وفخذيه عن ساقيه، ورافعًا ذراعيه عن الأرض، هذا هو السجود المعتدل، ما يربض ضامًا بعضه إلى بعض؛ بطنه على فخذيه وفخذيه على ساقيه وذراعيه على الأرض مثل ربض البهيمة، هذا مكروه لا ينبغي، لكن السنة أن يسجد سجودًا معتدلًا، ليس برابض، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/13356/معنى-الربض-في-السجود","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_644/nour_64412.mp3","categories":["الأدعية والأذكار","التكبير والاستفتاح","الركوع والسجود"]},{"id":14848,"question":"هذه رسالة وصلت إلى البرنامج من بغداد، باعثها المستمع شاكر أبو محمود، يقول فيها: في الصلاة وأثناء السجود مما يدعو إلى إطالة السجود نقوم بعض الأحيان برفع الرأس، أو تحريكه يمينًا وشمالًا عن موضع السجود للاستراحة، أو نحو ذلك من الأسباب، فهل يعتبر ذلك نهاية لتلك السجدة، ولا يجوز بعدها الاستمرار بالسجود أم كيف توجهون الناس؟","title":"حكم رفع الرأس وتحريكه يمينًا وشمالًا في السجود","answer":"الجواب: هذا العمل مكروه، ولا ينبغي؛ لأن هذا عبث، ولكن يسجد طاقته، ولا يطول تطويلًا يلجئه إلى هذا العمل، يسجد يأتي بالتسبيح ثلاث مرات، أو خمس مرات، ويدعو بما تيسر، ثم يرفع، لا يكلف نفسه، وإذا كان إمامًا كذلك لا يشق على الناس، أما أنه يرفع رأسه ويومي به هذا لا، مكروه، وهو من العبث الذي لا ينبغي، وإذا كثر قد يبطل الصلاة إذا كثر وتوالى، لكن بكل حال هو مكروه، ولا ينبغي، والسجود باقي إذا رفع رأسه قليل، ثم وضعه، فهذا من كمال السجود ما يبطل السجود، لكن لا ينبغي هذا العمل، بل يسجد ما يسر الله له، ثم يرفع رفعًا تامًا، ويأتي بالسجدة الثانية، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/13353/حكم-رفع-الراس-وتحريكه-يمينا-وشمالا-في-السجود","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_644/nour_64409.mp3","categories":["الأدعية والأذكار","التكبير والاستفتاح","الركوع والسجود"]},{"id":14895,"question":"سؤال طويل لأخينا كالتالي: يقول الرسول ﷺ في حديث له: أما الركوع فعظموا فيه الرب، وأما السجود فاجتهدوا في الدعاء، فقمن أن يستجاب لكم وفي صلاة للرسول ﷺ قال رجل -عند الرفع من الركوع بعد قوله: ربنا ولك الحمد- \"حمدًا كثيرًا طيبًا مباركًا فيه\" وعندما انتهى الرسول ﷺ من الصلاة سأل عن القائل لهذا الكلام، فقال الرجل: أنا يا رسول الله، فقال ﷺ: لقد رأيت بضعًا وثلاثين ملكًا يبتدرونها، أيهم يكتبها أول فأقر رسول الله ﷺ ما قاله الرجل،  هل يفهم مما تقدم أن يقول الواحد في صلاته في الركوع مما يرى فيه تعظيمًا للرب كقوله: سبحانك يا مالك زمام الخلق، وبيده كل شيء، أحمدك حمدًا كثيرًا، مما فيه تعظيم للرب؟ أو أن يقول في السجود بأي دعاء من أمر الدنيا والآخرة، وأقصد بذلك عدم الاقتصار على أذكار الركوع والسجود الواردة عن رسول الله ﷺ؛ وذلك لأن الصحابة كانوا يأتون بدعاء فيقره رسول الله ﷺ؟","title":"حكم تعظيم الرب في الركوع بما لم يرد في السنة","answer":"الجواب: الحديث المذكور في النهي عن القراءة راكعًا وساجدًا ثابت، رواه مسلم في الصحيح عن ابن عباس -رضي الله تعالى عنهما-، عن النبي ﷺ أنه قال: إني نهيتُ أن أقرأ القرآن راكعًا أو ساجدًا، فأما الركوع فعظموا فيه الرب، وأما السجود فاجتهدوا في الدعاء، فقمن أن يستجاب لكم المعنى: حري أن يستجاب لكم، وقد روي معنى شطره الأول عن علي ، أنه ثبت عن علي أيضًا  في النهي عن القراءة راكعًا أو ساجدًا، فلا يجوز للمسلم أن يقرأ في الركوع والسجود، لكن لو دعا في السجود بدعاء يوافق ما في القرآن لم يكن قارئًا، إذا أراد الدعاء فقط، كأن يقول: رَبَّنَا آتِنَا فِي الدُّنْيَا حَسَنَةً وَفِي الآخِرَةِ حَسَنَةً وَقِنَا عَذَابَ النَّارِ [البقرة:201] ، رَبَّنَا لا تُزِغْ قُلُوبَنَا بَعْدَ إِذْ هَدَيْتَنَا وَهَبْ لَنَا مِنْ لَدُنْكَ رَحْمَةً إِنَّكَ أَنْتَ الْوَهَّابُ [آل عمران:8] لا يقصد القراءة يقصد الدعاء فلا حرج في ذلك، وكذلك إذا عظم الرب بأنواع من التعظيم لم ترد لا بأس؛ لأن الرسول ﷺ قال: عظموا فيه الرب فعمم، فإذا قال من التعظيم ما قاله السائل، أو اقتصر على الوارد كله طيب، وكونه يقتصر على الوارد، ويكثر من الوارد، ويكرر أفضل؛ ولهذا قال ﷺ لما سمع الرجل قال: حمدًا كثيرًا طيبًا، قال: لقد رأيت -كذا مثلما في السؤال- بضعًا وثلاثين ملكًا يبتدرونها، أيهم يكتبها فأقرها. فدل ذلك على استحباب مثل هذا التحميد، أن يقول: ربنا ولك الحمد حمدًا كثيرًا طيبًا مباركًا فيه ملء السماوات، وملء الأرض، وملء ما بينهما، وملء ما شئت من شيء بعد؛ لأن الرسول ﷺ فعل بعض هذا، وأقر هذه الزيادة \"حمدًا كثيرًا\" وكان يقول ﷺ: ربنا ولك الحمد وربما قال: اللهم ربنا لك الحمد، ملء السماوات، وملء الأرض، وملء ما بينهما، وملء ما شئت من شيء بعد فلما أقر الرجل على قوله: \"حمدًا كثيرًا\" إلى آخره دل على شرعية ذلك، وأن يقول: ربنا ولك الحمد، أو اللهم ربنا لك الحمد حمدًا كثيرًا طيبًا مباركًا فيه، ملء السماوات، وملء الأرض، وملء ما بينهما وملء ما شئت من شيء بعد؛ لأن هذا كله ثناء. وكان ﷺ ربما زاد: أهل الثناء والمجد، أحق ما قال العبد، وكلنا لك عبد، اللهم لا مانع لما أعطيت، ولا معطي لما منعت، ولا ينفع ذا الجد منك الجد في وقوفه بعد الركوع، في اعتداله بعد الركوع، كل هذا مشروع، أقله اللهم ربنا لك الحمد، أو ربنا ولك الحمد، هذا الواجب عند جمع من أهل العلم، وأكثر أهل العلم على أنه سنة، لكن القول بوجوب هذا المقدار هو الأصح؛ لأن الرسول أمر به -عليه الصلاة والسلام-، وما زاد على ذلك فهو كله سنة. قوله: حمدًا كثيرًا طيبًا مباركًا فيه وقوله: ملء السماوات وملء الأرض، وملء ما بينهما، وملء ما شئت من شيء بعد كل هذا سنة، كذلك قوله: أهل الثناء والمجد، أحق ما قال العبد، وكلنا لك عبد، اللهم لا مانع لما أعطيت، ولا معطي لما منعت، ولا ينفع ذا الجد منك الجد يعني: ولا ينفع ذا الغنى والحظ والبخت منك غناه، فالمعنى: كلنا فقراء إلى الله ، فإذا أتى بهذا تارة وحذفه تارة فلا بأس لأنه سنة. والدعاء كذلك يدعو بما يسر الله من الدعاء، ولكن تحري الدعاء الوارد أفضل، كما أنه يتحرى التعظيم الوارد في الركوع والسجود سبحانك اللهم ربنا وبحمدك، اللهم اغفر لي هذا مما ورد في الركوع والسجود سبحانك اللهم ربنا وبحمدك، اللهم اغفر لي، سبوح قدوس، رب الملائكة والروح، سبحان ربي العظيم، سبحان ربي العظيم، سبحان ربي العظيم ولو قال: سبحان الملك العظيم، أو سبحان الله العظيم كله تعظيم كله تعظيم. لكن كونه يتحرى الأذكار الواردة في الركوع والدعوات الواردة في السجود كله طيب أفضل من غيره، ولكن إذا دعت الحاجة إلى أن يدعو بدعوات أخرى فيدعو؛ لقوله ﷺ: وأما السجود فاجتهدوا في الدعاء وللحديث الثاني رواه مسلم في الصحيح عن النبي ﷺ أنه قال: أقرب ما يكون العبد من ربه وهو ساجد، فأكثروا الدعاء رواه مسلم. فهذا يدل على أنه يشرع إكثار الدعاء في السجود بما يحتاجه المسلم، فإذا كان محتاجًا للزواج قال: اللهم يسر لي زوجة صالحة، أو للذرية اللهم يسر لي ذرية طيبة، أو لكسب حلال، قال: اللهم يسر لي كسبًا حلالًا كل هذا لا بأس به؛ لأن الحاجة تدعو إلى ذلك، وإذا أكثر من الدعوات المشروعة الواردة كان أفضل، مثل: اللهم اغفر لي ذنبي كله، دقه وجله، وأوله وآخره، وعلانيته وسره؛ لأن هذا ورد عن النبي ﷺ. كذلك: اللهم إني ظلمت نفسي ظلمًا كثيرًا، ولا يغفر الذنوب إلا أنت، فاغفر لي مغفرة من عندك وارحمني إنك أنت الغفور الرحيم هذا دعاء وارد عن النبي ﷺ، أو اللهم اغفر لي ما قدمت وما أخرت، وما أسررت وما أعلنت، وما أسرفت وما أنت أعلم به مني، أنت المقدم وأنت المؤخر، لا إله إلا أنت هذا من الدعاء الوارد، ولكن يشرع مع هذا أن يقول: سبوح قدوس، رب الملائكة والروح يقوله في السجود كما يقوله في الركوع أيضًا، ويقول: سبحانك اللهم ربنا وبحمدك اللهم اغفر لي في الركوع والسجود، هذا تعظيم معه دعاء، قالت عائشة -رضي الله عنها-: كان النبي ﷺ يكثر أن يقول في ركوعه وسجوده: سبحانك اللهم ربنا وبحمدك، اللهم اغفر لي نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/13396/حكم-تعظيم-الرب-في-الركوع-بما-لم-يرد-في-السنة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_492/49203.mp3","categories":["الأدعية والأذكار","التكبير والاستفتاح","الركوع والسجود"]},{"id":15059,"question":"صالح بن محمد الصالح من سدير، يقول في رسالته:بسم الله الرحمن الرحيم. فضيلة الشيخ عبدالعزيز بن عبدالله بن باز، أدامه الله وأمد في عمره على زيادة عمل صالح وفائدة للمسلمين، وبعد: فإني أسألكم عن أمور تهمني في الصلاة، أرجو أن أجد إجابات لها منكم شافية كافية مبسوطة، وفقكم الله.يقول في السؤال الأول: ما حكم من وجد الإمام راكعًا في الهواء فكبر تكبيرة الإحرام، ثم أدخل تكبيرة الركوع فيها، هل تصح صلاته أم لا؟","title":"هل تجزئ تكبيرة الإحرام لمن أدرك الإمام راكعًا؟","answer":"الجواب: بسم الله الرحمن الرحيم.  الحمد لله رب العالمين، وصلى الله وسلم وبارك على عبده ورسوله محمد وعلى آله وأصحابه أجمعين، أما بعد: فإن من أدرك الإمام راكعًا تجزئه، أي: التكبيرة الأولى في أصح قولي العلماء؛ لأنها هي الفريضة العظمى، وهي الركن الأعظم، ولا تنعقد الصلاة إلا بها، أما تكبيرة الركوع فهي قيل بوجوبها، وقيل بسنيتها، فهي أدنى من التكبيرة الأولى، فإذا ضاق الوقت أجزت التكبيرة الأولى، وهي العظمى، وهي الركن عن التكبيرة الثانية تكبيرة الركوع، وإن أتى بهما جميعًا فذلك أفضل وأحوط، ثم يركع يكبر الأولى، وهو قائم ثم يكبر منحطًا للركوع، وهذا هو الكمال، وإن لم يكبر الثانية واقتصر على الأولى أجزأه ذلك على الصحيح، نعم.","link":"https://binbaz.org.sa/fatwas/13544/هل-تجزى-تكبيرة-الاحرام-لمن-ادرك-الامام-راكعا","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_663/nour_66301.mp3","categories":["التكبير والاستفتاح","النية في الصلاة"]},{"id":15239,"question":"هذه رسالة وردتنا من أحد السادة المستمعين، يقول في رسالته: السؤال الأول: كنت أصلي وما زلت والحمد لله، ولكن بداية صلاتي كنت أصلي نصف صلاة، أي: مثل صلاة الفجر سجدتين، أتصور أني أصلي صلاة كاملة، وكذلك صلاة الظهر أربع ركعات، كنت أصليها أربع سجدات، وكذلك الفرض...الشيخ: أعد، أعد.المقدم: يقول: كنت أصلي وما زلت والحمد لله، ولكن بداية صلاتي كنت أصلي نصف صلاة، أي: مثل صلاة الفجر سجدتين أتصور أني أصلي صلاة كاملة، وكذلك صلاة الظهر أربع ركعات كنت أصليها أربع سجدات، وكذلك الفرض لصلوات أخرى، ويقول: استمريت على هذا المنهج حوالي أربع سنوات، والأمر الذي جعلني أستمر على هذا الخطأ هو الحياء، أستحي أن أسأل أحدًا حتى والدي الذي هو معي في البيت، وإني مقتنع إذا سألته سوف يجيبني بالحقيقة، لكن لم أسأله، وبعد هذه الفترة الطويلة -أي: أربع سنوات- أو أقل أو أكثر، فإني سألت أحد الأشخاص، وقال لي: إن صلاتك نصف الفرض. سؤالي: هل علي قضاء؟ وكيف أصليها قضاء؟الله يوفقكم ويوفقنا لما فيه الخير.","title":"حكم من يسجد سجدة واحدة في كل ركعة جهلًا","answer":"الجواب: هذه المسألة غريبة جدًا، رجل بين المسلمين تخفى عليه صفة الصلاة، ويصلي في كل ركعة سجدة واحدة، لا حول ولا قوة إلا بالله، لا ريب أن هذا من ثمرات التخلف عن الصلاة في الجماعة، لو كان السائل يصلي في الجماعة لعرف كيف يصلي، ولرأى الناس يصلون سجدتين في كل ركعة، ولكن بسبب صلاته في البيت، وعدم السؤال وقع في هذا الغلط الكبير. والعلم يطلب، ويسأل عنه، ولا يستحيا في طلبه، يقول الله -جل وعلا-: إِنَّ اللَّهَ لا يَسْتَحْيِي أَنْ يَضْرِبَ مَثَلًا مَا بَعُوضَةً فَمَا فَوْقَهَا[البقرة:26] ويقول سبحانه في آية الأحزاب: وَاللَّهُ لا يَسْتَحْيِي مِنَ الْحَقِّ[الأحزاب:53] فهو  لا يستحي أن يقول الحق، وأن يأمر بالحق -جل وعلا-، وتقول أم سليم لما سألت النبي ﷺ: «يا رسول الله! إن الله لا يستحي من الحق، هل على المرأة من غسل إذا هي احتلمت؟ فقال النبي ﷺ: نعم، إذا هي رأت الماء. فالحق ليس فيه حياء، أن يسأل عنه، ويتفقه فيه المسلم والمسلمة، وقال مجاهد بن جبر التابعي الجليل -رحمه الله-: \"لا يتعلم العلم مستح ولا مستكبر\" فالمستحي لا يتعلم، والمتكبر لا يتعلم، فلا يليق بالمؤمن أن يستحي في العلم، وهذا ليس بحياء في الحقيقة، ولكنه ضعف وخور وتهاون وتكاسل، وإلا فالحياء الصحيح الحياء المشروع يدعو إلى الخير، ولا يمنع من الخير، مثلما قال النبي ﷺ: الحياء خير كله، الحياء لا يأتي إلا بخير، الحياء من الإيمان. فالحياء كله خير، وهو خلق كريم، يدعو إلى مكارم الأخلاق، ومحاسن الأعمال، وينهى عن سفاسف الأخلاق، وسيىء الأعمال. والذي يظهر من الشريعة أنك -أيها السائل- ليس عليك القضاء؛ لأنك في حكم المتعمد لعدم سؤالك مع تيسر السؤال، وعلى فرض أنك جاهل، وأنك تظن أن هذا هو الصواب، فإن المدة قد طالت، والجهل بهذا عظيم، فعليك التوبة والإنابة إلى الله والاستغفار، وعدم العود إلى مثل هذا العمل، وعليك أن تسأل أهل العلم عن كل شيء، وأن تصلي مستقبلًا كما يصلي المسلمون، كل ركعة فيها ركوع وفيها سجدتان، كل ركعة في الفريضة والنافلة فيها ركوع في الهواء، وفيها سجدتان في الأرض، لا بد من هذا. فعليك أن تستقبل حياتك بهذه الصلاة؛ كل ركعة فيها ركوع وسجدتان، وعليك أن تصلي مع المسلمين في المساجد، ولا تصلي في البيت، الصلاة في المساجد مع المسلمين أمر لازم، وأمر مفترض، كما في الحديث عنه -عليه الصلاة والسلام- أنه قال: من سمع النداء فلم يأت فلا صلاة له إلا من عذر وسأله -عليه الصلاة والسلام- رجل أعمى، فقال: «يا رسول الله، ليس لي قائد يلائمني إلى المسجد، فهل لي من رخصة أن أصلي في بيتي؟ فقال له النبي -عليه الصلاة والسلام-: هل تسمع النداء بالصلاة؟ قال: نعم. قال: فأجب فأمره أن يجيب النداء، ولم يرخص له مع أنه أعمى بعيد الدار، ليس له قائد يلائمه، ومع هذا أمره أن يصلي في المسجد، ولم يرخص له في أن يصلي في بيته، فكيف بحال البصير والصحيح؟ حاله أقل عذرًا من ذلك، بل لا عذر له ما دام صحيحًا يسمع النداء بصيرًا، فهو أعظم من ذاك الذي ليس له قائد وهو أعمى، فالواجب عليه أعظم، فإذا كان الأعمى لا يعذر، فالذي هو بصير قوي قادر لا يعذر من باب أولى. والنبي ﷺ لما سأله الأعرابي الذي دخل المسجد فنقر الصلاة، قال له النبي ﷺ: ارجع فصل فإنك لم تصل صلاها ثلاث مرات، ثم قال: يا رسول الله، والذي بعثك بالحق لا أحسن غير هذا فعلمني، فقال له النبي ﷺ: إذا قمت إلى الصلاة فأسبغ الوضوء، ثم استقبل القبلة، فكبر، ثم اقرأ ما تيسر معك من القرآن، ثم اركع حتى تطمئن راكعًا، ثم ارفع حتى تعتدل قائمًا، ثم اسجد حتى تطمئن ساجدًا، ثم ارفع حتى تطمئن جالسًا، ثم اسجد حتى تطمئن ساجدًا، ثم افعل ذلك في صلاتك كلها هكذا أمره -عليه الصلاة والسلام- بأن يصلي، هكذا بالطمأنينة والاعتدال والخشوع، وعدم العجلة، ولم يأمره بقضاء الماضي، ما أمره بقضاء الصلوات الماضية التي لم يكملها، بل نقرها لجهله، وقلة بصيرته فلهذا أمره أن يستقبل أمره ويصلي صلاة مستقيمة يطمئن فيها لربه ويخشع، ولم يأمره بقضاء الماضي. فهكذا أنت؛ لأنك تركت الصلاة في الحقيقة عن جهل، وقلة بصيرة، وتفريط، فعليك التوبة إلى الله، والإنابة إليه، ولا يلزمك القضاء للمدة الماضية فيما يظهر من قواعد الشرع، ومن هذا الحديث الشريف، والله يتوب عليك، وعليك بالإكثار من الأعمال الصالحات والاستغفار، والاستكثار من ذكر الله  فإن الحسنات يذهبن السيئات، والله المستعان، نعم.","link":"https://binbaz.org.sa/fatwas/13740/حكم-من-يسجد-سجدة-واحدة-في-كل-ركعة-جهلا","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_669/nour_66902.mp3","categories":["الأدعية والأذكار","التكبير والاستفتاح","الركوع والسجود"]},{"id":15339,"question":"ماذا يجب على المأمومين إذا قال الإمام: الله أكبر، وسمع الله لمن حمده، هل يردوا بصوت ظاهر أم بسر، سواء أكانت الصلاة سرية أو جهرية؟ وهذا السائل من اليمن.","title":"كيف يكون تكبير المأموم ودعاؤه خلف الإمام؟","answer":"الجواب: إذا قال الإمام: سمع الله لمن حمده،.يقول المأموم: ربنا ولك الحمد، ولا حاجة إلى الجهر، يقول كلامًا يسمع نفسه، ربنا ولك الحمد؛ لقوله ﷺ: إذا قال الإمام: سمع الله لمن حمده، فقولوا: ربنا ولك الحمد هكذا أمر ﷺ، الإمام يقول: سمع الله لمن حمده، ربنا ولك الحمد.  أما المأموم فيقول عند الرفع: ربنا ولك الحمد، أو اللهم ربنا لك الحمد، أو ربنا لك الحمد، كله واسع، الحمد لله، نعم. المقدم: الحمد لله.","link":"https://binbaz.org.sa/fatwas/13842/كيف-يكون-تكبير-الماموم-ودعاوه-خلف-الامام","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_566/56616.mp3","categories":["الأدعية والأذكار","التكبير والاستفتاح","الركوع والسجود"]},{"id":15412,"question":"سؤالها الأخير تقول: ما حكم وضع المرفقين على الأرض أثناء السجود؟","title":"حكم وضع المرفقين على الأرض أثناء السجود","answer":"الجواب: هذا مكروه، ولا ينبغي، النبي ﷺ قال: إذا سجدت فضع كفيك وارفع مرفقيك و\"نهى عن افتراش كافتراش السبع\" فالسنة أن يرفع مرفقيه، سواء رجل أو امرأة، يرفع ذراعيه عن الأرض، ويعتمد على كفيه حال السجود، هذه هي السنة.","link":"https://binbaz.org.sa/fatwas/13920/حكم-وضع-المرفقين-على-الارض-اثناء-السجود","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_684/nour_68412.mp3","categories":["الأدعية والأذكار","التكبير والاستفتاح","الركوع والسجود"]},{"id":15522,"question":"سماحة الشيخ، يقول هذا السائل: عندما تكون الصلاة جهرية، هل يبدأ المأموم بدعاء الاستفتاح بعد تكبيرة الإحرام أم بعد قراءة الإمام للفاتحة؟","title":"متى يقرأ المأموم دعاء الاستفتاح في الصلاة الجهرية؟","answer":"الجواب: يبدأ بالاستفتاح بعد التكبير، إذا سكت الإمام في حال استفتاح الإمام يستفتح المأموم، أما إذا كان الإمام ما استفتح، شرع في القراءة من حين كبر، فالمأموم يسكت لا يستفتح، عليه الإنصات في الجهرية، لكن إذا سكت الإمام يستفتح، فالمأموم يستفتح أيضًا، نعم.","link":"https://binbaz.org.sa/fatwas/14063/متى-يقرا-الماموم-دعاء-الاستفتاح-في-الصلاة-الجهرية","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_691/nour_69112.mp3","categories":["التكبير والاستفتاح","صلاة الجماعة"]},{"id":15995,"question":"السائل يقول في هذا السؤال -سماحة الشيخ-: في الصلاة البعض من الناس يضعون الأيدي في السجود، والبعض تسبق الركبة أو الركبتين قبل اليدين، ما هي الطريقة الصحيحة للسجود؟","title":"ما السنة عند الهوي للسجود؟","answer":"الجواب: إذا كان قادرًا فالأفضل أن يقدم ركبتيه، ثم يديه، ثم جبهته، وأنفه هذا السنة، وعند الرفع يرفع رأسه ثم يديه، ثم ركبتيه، هذا إذا كان قادرًا، أما إذا كان عاجزًا فلا بأس أن يقدم يديه، والحمد لله، نعم.","link":"https://binbaz.org.sa/fatwas/14598/ما-السنة-عند-الهوي-للسجود","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_578/57818.mp3","categories":["الأدعية والأذكار","التكبير والاستفتاح","الركوع والسجود"]},{"id":16071,"question":"يسأل سؤالًا آخر فيقول: في صلاة النافلة، وكذلك الوتر، هل نقرأ فيها دعاء الاستفتاح، وكذلك التعوذ من الأربع التي أمر بها الرسول ﷺ: اللهم إني أعوذ بك من عذاب جهنم، وعذاب القبر، ومن فتنة المحيا والممات، ومن شر فتنة المسيح الدجال أم أن ذلك خاص بالفروض دون النافلة، وكذلك الدعاء بعد الفراغ من التعوذ من الأربع، هل يلزم في النافلة؟ وفقكم الله، وجزاكم خيرًا.","title":"مشروعية الاستفتاح والأدعية في النفل","answer":"الجواب: الاستفتاح مشروع في الجميع في النافلة والفريضة، مثل صلاة الضحى، وصلاة التراويح، صلاة التهجد، يستفتح الإنسان في أولها بعد التكبيرة الأولى، وهكذا الدعاء في آخر الصلاة، التعوذ من أربع، والدعاء بغيرها، كل ذلك حق كله مشروع في الفريضة والنافلة. ولما علمهم ﷺ التحيات قال: ثم ليتخير من الدعاء أعجبه إليه فيدعو وفي اللفظ الآخر قال: ثم ليختر من المسألة ما شاء. فالمسلم مشروع له، والمسلمة كذلك مشروع لهما جميعًا الدعاء في آخر الصلاة النافلة والفريضة، بعدما يصلي على النبي ﷺ يقول: اللهم إني أعوذ بك من عذاب جهنم، ومن عذاب القبر، ومن فتنة المحيا والممات، ومن فتنة المسيح الدجال ويدعو بما أحب: اللهم أعني على ذكرك، وشكرك، وحسن عبادتك. وهكذا الدعاء الذي علمه النبي أبا بكر علمه النبي ﷺ أبا بكر الصديق  وهو قوله: اللهم إني ظلمت نفسي ظلمًا كثيرًا، ولا يغفر الذنوب إلا أنت، فاغفر لي مغفرة من عندك، وارحمني إنك أنت الغفور الرحيم دعاء عظيم علمه النبي ﷺ للصديق، قال: يا رسول الله! علمني دعاء أدعو به في صلاتي، وفي بيتي، قال: قل: اللهم إني ظلمت نفسي ظلمًا كثيرًا، ولا يغفر الذنوب إلا أنت، فاغفر لي مغفرة من عندك، وارحمني إنك أنت الغفور الرحيم. وقال لمعاذ : يا معاذ! لا تدعن دبر كل صلاة أن تقول: اللهم أعني على ذكرك، وشكرك، وحسن عبادتك وكان -عليه الصلاة والسلام- يقول في آخر الصلاة: اللهم إني أعوذ بك من البخل، وأعوذ بك من الجبن، وأعوذ بك أن أرد إلى أرذل العمر، وأعوذ بك من فتنة الدنيا، ومن عذاب القبر وكان يقول أيضًا: اللهم اغفر لي ما قدمت، وما أخرت، وما أسررت، وما أعلنت، وما أسرفت، وما أنت أعلم به مني، أنت المقدم، وأنت المؤخر لا إله إلا أنت. هذه دعوات في آخر الصلاة، ويدعو بما أحب سواها مثل: اللهم اغفر لي ولوالدي، اللهم أنجني من النار، اللهم أصلح قلبي وعملي، اللهم ارزقني الرزق الحلال، اللهم أصلح لي شأني كله، وما أشبه ذلك، نعم.  المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/14701/مشروعية-الاستفتاح-والادعية-في-النفل","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_802/nour_80209.mp3","categories":["التكبير والاستفتاح","النية في الصلاة"]},{"id":16189,"question":"عند الرفع من الركوع هل من اللازم قول: الله أكبر، أم أنه لا يجوز في هذا الموضع؟ جزاكم الله خيرًا.","title":"الذكر الوارد عند الرفع من الركوع","answer":"الجواب: عند الرفع من الركوع إن كان إمامًا، أو منفردًا يقول: سمع الله لمن حمده، إذا كان إمامًا، أو منفردًا، أما إذا كان مأمومًا؛ فإنه يقول عند الرفع: ربنا ولك الحمد، أو اللهم ربنا ولك الحمد، كما جاء في الأحاديث الصحيحة عن رسول الله، عليه الصلاة والسلام. والإمام يقول بعد الرفع بعدما يقول: سمع الله لمن حمده، يقول: ربنا ولك الحمد، والمنفرد كذلك بعدما يقول: سمع الله لمن حمده، يقول: ربنا ولك الحمد. أما المأموم فعند الرفع يقول: ربنا ولك الحمد، أو اللهم ربنا لك الحمد، أربع صفات: ربنا لك الحمد، ربنا ولك الحمد، اللهم ربنا لك الحمد، اللهم ربنا ولك الحمد، كلها صفات جاءت في الأحاديث عند الرفع في حق المأموم.  أما الإمام، والمنفرد فإنه يقول هذا الكلام بعد الانتصاب، بعدما يقول: سمع الله لمن حمده، يأتي بربنا ولك الحمد، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/14869/الذكر-الوارد-عند-الرفع-من-الركوع","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_806/nour_80608.mp3","categories":["الأدعية والأذكار","التكبير والاستفتاح","الركوع والسجود"]},{"id":16197,"question":"من المستمع معيوف مصيلح رسالة وضمنها جمعًا من الأسئلة، في أحدها يقول: إذا بدأ الإمام بصلاة التراويح، وقرأ دعاء الاستفتاح بعد تكبيرة الإحرام، ثم شرع في قراءة الفاتحة، ثم فيما بعدها من القرآن الكريم، ثم أتى بالركعة الثانية، ثم سلم، فبدأ بتكبيرة الإحرام الثانية، هل يقرأ أيضًا دعاء الاستفتاح؟ أم يكفيه في المرة الأولى؟ جزاكم الله خيرًا.","title":"مشروعية تكرار دعاء الاستفتاح في صلاة التراويح","answer":"الجواب: يكفيه في المرة الأولى، الاستفتاح في الأولى فقط، في أول ركعة، في الفريضة والنافلة، بعد تكبيرة الإحرام يستفتح، ولا يشرع أن يعاد في الثانية، ولا في الثالثة، لكن إذا شرع في التسليمة الثانية في التراويح، أو النافلة يستفتح أيضًا، كلما صلى ركعتين، وقام، وكبر؛ يستفتح، هذا هو السنة، في النافلة والفريضة، مثل صلاة التراويح في رمضان، مثل صلاة الضحى، يصلي تسليمتين، أو أكثر، يستفتح في كل تسليمة هذا هو الأفضل، بعد التكبيرة الأولى يعني، بعد تكبيرة الإحرام، يقول: سبحانك اللهم وبحمدك، وتبارك اسمك، وتعالى جدك، ولا إله غيرك أو يأتي بأي نوع من الاستفتاحات الأخرى الصحيحة، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/14898/مشروعية-تكرار-دعاء-الاستفتاح-في-صلاة-التراويح","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_806/nour_80614.mp3","categories":["التكبير والاستفتاح","النية في الصلاة"]},{"id":16206,"question":"عند الرفع من الركوع هل من اللازم قول: الله أكبر، أم أنه لا يجوز في هذا الموضع؟ جزاكم الله خيرًا.","title":"الذكر الوارد عند الرفع من الركوع","answer":"الجواب: عند الرفع من الركوع إن كان إمامًا، أو منفردًا يقول: سمع الله لمن حمده، إذا كان إمامًا، أو منفردًا، أما إذا كان مأمومًا؛ فإنه يقول عند الرفع: ربنا ولك الحمد، أو اللهم ربنا ولك الحمد، كما جاء في الأحاديث الصحيحة عن رسول الله، عليه الصلاة والسلام. والإمام يقول بعد الرفع بعدما يقول: سمع الله لمن حمده، يقول: ربنا ولك الحمد، والمنفرد كذلك بعدما يقول: سمع الله لمن حمده، يقول: ربنا ولك الحمد. أما المأموم فعند الرفع يقول: ربنا ولك الحمد، أو اللهم ربنا لك الحمد، أربع صفات: ربنا لك الحمد، ربنا ولك الحمد، اللهم ربنا لك الحمد، اللهم ربنا ولك الحمد، كلها صفات جاءت في الأحاديث عند الرفع في حق المأموم.  أما الإمام، والمنفرد فإنه يقول هذا الكلام بعد الانتصاب، بعدما يقول: سمع الله لمن حمده، يأتي بربنا ولك الحمد، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/14869/الذكر-الوارد-عند-الرفع-من-الركوع","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_806/nour_80608.mp3","categories":["الأدعية والأذكار","التكبير والاستفتاح","الركوع والسجود"]},{"id":16227,"question":"المستمعة أسماء محمود عثمان مقيمة في المملكة تقول: أريد أن أعرف دعاء السجود الخاص بالسجود؟ وهل هناك دعاء للركوع؟ جزاكم الله خيرًا.","title":"أدعية الركوع والسجود","answer":"الجواب: السجود يدعو فيه المؤمن بما يسر الله له، السجود يدعو فيه المؤمن والمؤمنة بما يسر الله من الدعوات الطيبة، ولو لم تنقل عن النبي ﷺ، ومن دعاء النبي ﷺ: اللهم اغفر لي ذنبي كله، دقه وجله، وأوله وآخره، وعلانيته وسره ثبت عنه أنه كان يدعو بهذا في السجود -عليه الصلاة والسلام-: اللهم اغفر لي ذنبي كله، دقه وجله، وأوله وآخره، وعلانيته وسره وإذا دعا الإنسان في السجود بغير هذا، مثل: اللهم يا مقلب القلوب ثبت قلبي على دينك، ويا مصرف القلوب صرف قلبي على طاعتك اللهم إنك عفو، تحب العفو فاعف عني اللهم اغفر لي، ولوالدي -إذا كان والداه مسلمين- اللهم اغفر لي ولوالدي، ولجميع المسلمين، اللهم أصلح قلبي وعملي، وما أشبه ذلك من الدعوات الطيبة. ويستحب أن يقول في الركوع والسجود: سبحانك اللهم ربنا وبحمدك، اللهم اغفر لي فهو تعظيم معه دعاء يقال في الركوع والسجود: سبحانك اللهم ربنا وبحمدك، اللهم اغفر لي ولكن الركوع لا يدعى فيه إلا بهذا فقط، الركوع محل تعظيم، يقول النبي ﷺ: أما الركوع فعظموا فيه الرب، وأما السجود فاجتهدوا في الدعاء؛ فقمن أن يستجاب لكم يعني: فحري أن يستجاب لكم. لكن إذا قال في الركوع: سبحانك اللهم ربنا وبحمدك، اللهم اغفر لي فهذا مشروع، كان يفعله النبي ﷺ وهذه الدعوة تابعة (اللهم اغفر لي) تابعة للتعظيم؛ فلا حرج فيها، نعم. المقدم: جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/14914/ادعية-الركوع-والسجود","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_751/nour_75119.mp3","categories":["الأدعية والأذكار","التكبير والاستفتاح","الركوع والسجود"]},{"id":16228,"question":"تقول: سمعت بأنه لا تجوز قراءة القرآن أثناء السجود، فهل يجوز قراءة الأدعية الموجودة في القرآن مثال: رَبَّنَا آتِنَا فِي الدُّنْيَا حَسَنَةً وَفِي الآخِرَةِ حَسَنَةً وَقِنَا عَذَابَ النَّارِ [البقرة:201]؟","title":"حكم الدعاء بالأدعية الواردة في القرآن في السجود","answer":"الجواب: الرسول ﷺ نهى عن قراءة القرآن في الركوع والسجود، لكن إذا دعا الإنسان بالدعوات القرآنية من غير قصد للقراءة؛ فلا حرج، مثل الآية التي ذكرت السائلة: رَبَّنَا آتِنَا فِي الدُّنْيَا حَسَنَةً وَفِي الآخِرَةِ حَسَنَةً وَقِنَا عَذَابَ النَّارِ [البقرة:201] ومثل قوله سبحانه: رَبَّنَا لا تُزِغْ قُلُوبَنَا بَعْدَ إِذْ هَدَيْتَنَا وَهَبْ لَنَا مِنْ لَدُنْكَ رَحْمَةً إِنَّكَ أَنْتَ الْوَهَّابُ [آل عمران:8] لا حرج في ذلك بنية الدعاء، نعم. المقدم: جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/14909/حكم-الدعاء-بالادعية-الواردة-في-القران-في-السجود","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_751/nour_75117.mp3","categories":["الأدعية والأذكار","التكبير والاستفتاح","الركوع والسجود"]},{"id":16403,"question":"عبدالله أبو عمر من الأردن، يقول: سماحة الشيخ! خلال أيام الشتاء أشعر بالبرد الشديد في يدي، هل يجوز لي أن أرتدي قفازات من الصوف في يدي، وأنا أصلي بهما، هل هذا ينافي السجود على السبعة أعضاء، ومنها اليدين؟","title":"هل الصلاة بالقفازين ينافي السجود على الأعضاء السبعة؟","answer":"الجواب: لا حرج في ذلك، ولو جعلت القفازين مثلما تجعل في رجليك الخفين، لا حرج والحمد لله، إذا جعلت القفازين في يديك للدفء، أو جعلتها في غترتك، شماغك، أو غيرها، أو في بشتك، وسجدت عليه؛ فلا بأس، الأمر واسع الحمد لله، كان الصحابة -رضي الله عنهم وأرضاهم- إذا اشتد عليهم حر الأرض سجدوا على ثيابهم، نعم. المقدم: أحسن الله إليكم يا سماحة الشيخ.","link":"https://binbaz.org.sa/fatwas/15107/هل-الصلاة-بالقفازين-ينافي-السجود-على-الاعضاء-السبعة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_581/58121.mp3","categories":["الأدعية والأذكار","التكبير والاستفتاح","الركوع والسجود"]},{"id":16743,"question":"من العراق رسالة بعث بها المستمع حامد يونس إبراهيم من الموصل يقول: عند الركوع هل وضع اليدين أصح من وضع الركبتين أولًا، أو بالعكس؟ جزاكم الله خيرًا.","title":"السنة تقديم الركبتين عند الهوي للسجود","answer":"الجواب: الأصح، والأفضل أن يضع ركبتيه أولًا، كان النبي ﷺ يضع ركبتيه ثم يديه ﷺ وينهى عن بروك كبروك البعير، والبعير إذا برك يقدم يديه، فالسنة أن تقدم ركبتيك لا يديك، والأحاديث في الحقيقة متفقة، لا مختلفة، وهي السجود على الركبتين، ثم اليدين، ثم الجبهة والأنف، والرفع يرفع رأسه، ثم يديه، ثم ركبتيه. نعم، هذا هو الأرجح، والأفضل، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/15492/السنة-تقديم-الركبتين-عند-الهوي-للسجود","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_821/nour_82105.mp3","categories":["الأدعية والأذكار","التكبير والاستفتاح","الركوع والسجود"]},{"id":16744,"question":"من العراق رسالة بعث بها المستمع حامد يونس إبراهيم من الموصل يقول: عند الركوع هل وضع اليدين أصح من وضع الركبتين أولًا، أو بالعكس؟ جزاكم الله خيرًا.","title":"السنة تقديم الركبتين عند الهوي للسجود","answer":"الجواب: الأصح، والأفضل أن يضع ركبتيه أولًا، كان النبي ﷺ يضع ركبتيه ثم يديه ﷺ وينهى عن بروك كبروك البعير، والبعير إذا برك يقدم يديه، فالسنة أن تقدم ركبتيك لا يديك، والأحاديث في الحقيقة متفقة، لا مختلفة، وهي السجود على الركبتين، ثم اليدين، ثم الجبهة والأنف، والرفع يرفع رأسه، ثم يديه، ثم ركبتيه. نعم، هذا هو الأرجح، والأفضل، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/15492/السنة-تقديم-الركبتين-عند-الهوي-للسجود","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_821/nour_82105.mp3","categories":["الأدعية والأذكار","التكبير والاستفتاح","الركوع والسجود"]},{"id":16879,"question":"ماهي الأذكار الصحيحة داخل الصلاة، وبعد التسليم؟ جزاكم الله خيرًا.","title":"ما الأذكار التي تقال في الصلاة؟","answer":"الجواب: داخل الصلاة يشرع له الاستفتاح في أولها بعدما يكبر يقول: الله أكبر التكبيرة الأولى -وهي التي تسمى تكبيرة الإحرام- يستفتح كما كان النبي يفعل هذا -عليه الصلاة والسلام- ومن ذلك: سبحانك اللهم وبحمدك، وتبارك اسمك، وتعالى جدك، ولا إله غيرك هذا يسمى الاستفتاح، وهو أخصرها.  ومن ذلك: ما كان يفعله النبي ﷺ أيضًا اللهم باعد بيني وبين خطاياي كما باعدت بين المشرق والمغرب، اللهم نقني من خطاياي كما ينقى الثوب الأبيض من الدنس، اللهم اغسلني من خطاياي بالثلج والماء والبرد وهناك استفتاحات أخرى صحيحة موجودة في كتب الحديث: كالمنتقى، وبلوغ المرام، والبخاري، وصحيح مسلم .. إلى غير ذلك. لكن هذان الاستفتاحان من أخصر الاستفتاحات. ثم يقول: أعوذ بالله من الشيطان الرجيم، بسم الله الرحمن الرحيم، ثم يقرأ الفاتحة (الحمد) ثم يقرأ ما تيسر معه إن كان إمامًا، أو منفردًا، أو مأمومًا في السرية صلاتي الظهر والعصر، وإن كان مأمومًا في الجهرية؛ قرأ الفاتحة فقط، وسكت، ينصت لإمامه، يستمع للإمام. وإذا كبر للركوع يقول: سبحان ربي العظيم سبحان ربي العظيم يكررها ثلاثًا، أو أكثر، والواجب مرة، سبحان ربي العظيم مرة واحدة الواجب، والتكرار مستحب، ويقول بعد ذلك: سبحانك اللهم ربنا وبحمدك، اللهم اغفر لي مستحب أيضًا، ويقول: سبوح قدوس، رب الملائكة والروح هذا مستحب أيضًا في الركوع، والسجود. وإذا رفع -كان إمامًا أو منفردًا- يقول: سمع الله لمن حمده وإن كان مأمومًا يقول: ربنا ولك الحمد أو اللهم ربنا لك الحمد حمدًا كثيرًا طيبًا مباركًا فيه، ملء السموات، وملء الأرض، وملء ما بينهما، وملء ما شئت من شيء بعد وإن زاد أهل الثناء والمجد، أحق ما قال العبد، وكلنا لك عبد، اللهم لا مانع لما أعطيت، ولا معطي لما منعت، ولا ينفع ذا الجد منك الجد كان أفضل؛ لأنه ثابت عن النبي ﷺ وإذا اقتصر على ما تقدم قوله: وملء ما شئت من شيء بعد كفى، والواجب ربنا ولك الحمد أو اللهم ربنا لك الحمد والبقية سنة ومستحب. المقدم: جزاكم الله خيرًا. الشيخ: وهكذا في السجود يكبر، بعدما يكبر للسجود يقول: سبحان ربي الأعلى، سبحان ربي الأعلى، في الركوع يقول: سبحان ربي العظيم في السجود، سبحان ربي الأعلى، سبحان ربي الأعلى، ويقول مع هذا: سبحانك اللهم ربنا وبحمدك، اللهم اغفر لي سبوح قدوس رب الملائكة والروح ويدعو في السجود ما تيسر، يدعو، مشروع في السجود الدعاء منها: اللهم اغفر لي ذنبي كله.. دقه وجله، وأوله وآخره، وعلانيته وسره. يقول النبي ﷺ: أقرب ما يكون العبد من ربه وهو ساجد، فأكثروا الدعاء ويقول ﷺ: «أما الركوع فعظموا فيه الرب، وأما السجود فاجتهدوا في الدعاء؛ فقمن أن يستجاب لكم يعني: حري أن يستجاب لكم، ويدعو بما يسر الله له من خير الدنيا والآخرة في السجود، في الفرض، والنفل للحديثين المذكورين، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/15634/ما-الاذكار-التي-تقال-في-الصلاة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_764/nour_76416.mp3","categories":["الأدعية والأذكار","التكبير والاستفتاح","الركوع والسجود"]},{"id":17001,"question":"ماذا إذا لم يدرك المصلي مع الإمام تكبيرة الإحرام، بل وجد الإمام يقرأ في السورة الثانية بعد الفاتحة مثلًا، هل يبدأ بالاستفتاح، أم بالفاتحة؟ جزاكم الله خيرًا.","title":"حكم بدء المسبوق بدعاء الاستفتاح","answer":"الجواب: يكبر، ويقرأ الفاتحة إذا كان يخشى ركوع الإمام، أما إن كان يعرف من حال الإمام، وقراءته أنه يمديه أن يستفتح، ويأتي بالفاتحة فلا بأس، لكن الأقرب -والله أعلم- أنه لا يستفتح، خصوصًا إذا كان بالجهرية لا يستفتح؛ لأنه مأمور بالإنصات، لكن الفاتحة مستثناة، يأتي بالفاتحة، ولا يستفتح. أما إذا كانت سرية، ويظن أنه يمكنه أن يستفتح، ويقرأ؛ فيستفتح، ثم يقرأ الفاتحة، يستفتح بالاستفتاح المختصر: سبحانك اللهم وبحمدك، وتبارك اسمك، وتعالى جدك، ولا إله غيرك ويأتي بالفاتحة، هذا في السرية، أما في الجهرية لا؛ لأنه مأمور بالإنصات، فلا يأتي إلا بالفاتحة، يأتي بالفاتحة ويكفي، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/15790/حكم-بدء-المسبوق-بدعاء-الاستفتاح","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_767/nour_76702.mp3","categories":["التكبير والاستفتاح","النية في الصلاة"]},{"id":17003,"question":"هل دعاء الاستفتاح في النوافل سنة، أفيدونا بارك الله فيكم، وأطال الله في عمركم على خير؟","title":"دعاء الاستفتاح سنة في الفرائض والنوافل","answer":"الجواب: دعاء الاستفتاح سنة في الفريضة والنافلة جميعًا، في التراويح.. في النوافل.. في صلاة الضحى، مثلما يستفتح في الفريضة يستفتح في النافلة، هذا هو السنة. نعم؛ لأن الرسول ﷺ قال: صلوا كما رأيتموني أصلي ولم يفرق بين النافلة والفريضة، والأصل أنهما سواء إلا بدليل، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/15775/دعاء-الاستفتاح-سنة-في-الفراىض-والنوافل","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_767/nour_76701.mp3","categories":["التكبير والاستفتاح","النية في الصلاة"]},{"id":17158,"question":"سماحة الشيخ، يقول: هل هذا صحيح دعاء الاستفتاح عندما أقول: قُلْ إِنَّ صَلاتِي وَنُسُكِي وَمَحْيَايَ وَمَمَاتِي لِلَّهِ رَبِّ الْعَالَمِينَ ۝ لا شَرِيكَ لَهُ [الأنعام:162-163]؟","title":"حكم استفتاح الصلاة بـ {قُلْ إِنَّ صَلاتِي وَنُسُكِي...}","answer":"الجواب: جاء نعم، كان النبي ﷺ يفعله في الليل، كان النبي ﷺ يستفتح في الليل يقول: وجهت وجهي للذي فطر السماوات والأرض حنيفًا، وما أنا من المشركين، إن صلاتي ونسكي هذا من دعاء الاستفتاح في الليل، فعله النبي ﷺ. أما في الفريضة فالأفضل: سبحانك اللهم وبحمدك، وتبارك اسمك، وتعالى جدك، ولا إله غيرك أو: اللهم باعد بيني وبين خطاياي كما باعدت بين المشرق والمغرب، اللهم نقني من خطاياي كما ينقى الثوب الأبيض من الدنس، اللهم اغسلني من خطاياي بالثلج والماء والبرد هذا المحفوظ عنه في صلاة الفريضة، عليه الصلاة والسلام. أما الاستفتاح المطول كان يفعله في الليل -عليه الصلاة والسلام- .. في التهجد. نعم.","link":"https://binbaz.org.sa/fatwas/15975/حكم-استفتاح-الصلاة-بـ-قل-ان-صلاتي-ونسكي","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_589/58935.mp3","categories":["التكبير والاستفتاح","النية في الصلاة"]},{"id":17366,"question":"ماذا يقول المسلم بين السجدتين في الصلاة، سواء كانت فرضًا، أم نفلًا؟","title":"ما يقوله المصلي بين السجدتين في الصلاة","answer":"الجواب: يقول: رب اغفر لي، رب اغفر لي، اللهم اغفر لي، وارحمني، واهدني، واجبرني، وارزقني، يكثر من ذلك: رب اغفر لي، رب اغفر لي، اللهم اغفر لي، وارحمني، واهدني، هكذا كان النبي يعمل ﷺ. المقدم: أحسن الله إليكم.","link":"https://binbaz.org.sa/fatwas/16200/ما-يقوله-المصلي-بين-السجدتين-في-الصلاة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_593/59326.mp3","categories":["الأدعية والأذكار","التكبير والاستفتاح","الركوع والسجود"]},{"id":17538,"question":"ما حكم من لم يقرأ دعاء الاستفتاح في الصلاة؟","title":"حكم ترك دعاء الاستفتاح","answer":"الجواب: لا حرج عليه، دعاء الاستفتاح مستحب وليس بواجب، فمن قرأه أجر ومن تركه فلا شيء عليه.\nالمقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/16464/حكم-ترك-دعاء-الاستفتاح","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_775/nour_77513.mp3","categories":["التكبير والاستفتاح","النية في الصلاة"]},{"id":17542,"question":"ماذا يفعل المسبوق إذا وجد المصلين في الجلوس هل يجلس بدون تكبيرة الإحرام ويأتي بها بعد القيام معهم، أم ماذا؟","title":"إذا وجد المسبوق الإمام جالسًا فمتى يكبر للإحرام؟","answer":"الجواب: لا، يكبر أولًا وهو واقف تكبيرة الإحرام ثم يجلس، يكبر تكبيرة الإحرام وهو واقف ثم يجلس معهم. نعم.\nالمقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/16496/اذا-وجد-المسبوق-الامام-جالسا-فمتى-يكبر-للاحرام","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_838/nour_83815.mp3","categories":["التكبير والاستفتاح","صلاة الجماعة"]},{"id":17606,"question":"من أسئلته أيضًا يقول: هل هناك ذكر مشروع بعد إقامة الصلاة وقبل تكبيرة الإحرام؟","title":"هل يوجد ذكر بين الإقامة وتكبيرة الإحرام؟","answer":"الجواب: لا أعلم شيئًا في ذلك، لم يرد في هذا شيء فيما نعلم. نعم.","link":"https://binbaz.org.sa/fatwas/16535/هل-يوجد-ذكر-بين-الاقامة-وتكبيرة-الاحرام","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_594/59414.mp3","categories":["التكبير والاستفتاح","النية في الصلاة"]},{"id":17651,"question":"سماحة الشيخ حفظكم الله، هذا سائل يقول: في حديث ما معناه بأنه عند السجود كان يفتح بين أصابع رجليه، ما معنى الفتح وكيفيته، وكذلك عند التشهد الأخير؟","title":"وضعية أصابع اليدين والرجلين عند الركوع والسجود","answer":"الجواب: يعتمد على بطون أصابع رجليه مفتوحتان، يعتمد على أصابع رجليه حين السجود، ويعتمد على كفيه حين السجود كذلك، فالأصابع في الكفين مقبوضة إذا لصق بعضها ببعض مادًا لها، أما الرجلين يعتمد على بطون أصابعها وهو موقف لها، ويعتمد على بطون الأصابع. نعم.","link":"https://binbaz.org.sa/fatwas/16580/وضعية-اصابع-اليدين-والرجلين-عند-الركوع-والسجود","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_594/59423.mp3","categories":["الأدعية والأذكار","التكبير والاستفتاح","الركوع والسجود"]},{"id":17792,"question":"في ثاني أسئلة السائلة أم خالد من الباحة تقول سماحة الشيخ: في أثناء السجود وبعد التسبيح أدعو بأدعية عارضة أي: من الحياة، مثل أن أدعو بالمغفرة لي ولوالدي أو أن يحفظ لي...الشيخ: أعد أعد.المقدم: تقول السائلة: في أثناء السجود وبعد التسبيح أدعو بأدعية عارضة أي: من الحياة، مثل أن أدعو بالمغفرة لي ولوالدي، أو أن يحفظ لي أولادي.. وهكذا، فهل هذا يبطل الصلاة؛ لأنه كلام خارج عن أصل الصلاة؟","title":"حكم الدعاء بأمر دنيوي أثناء السجود","answer":"الجواب: كله طيب، الدعاء في السجود طيب قال النبي ﷺ: أما الركوع فعظموا فيه الرب، وأما السجود فاجتهدوا في الدعاء فقمن أن يستجاب لكم يعني: فحري أن يستجاب لكم، وقال عليه الصلاة والسلام: أقرب ما يكون العبد من ربه وهو ساجد فأكثروا الدعاء وهذا يعم دعاء الدنيا ودعاء الآخرة، وكان يقول في سجوده عليه الصلاة والسلام: اللهم اغفر لي ذنبي كله دقه وجله، وأوله وآخره، وعلانيته وسره، ويقول في ركوعه وسجوده: سبحانك اللهم ربنا وبحمدك اللهم اغفر لي.\nفإذا دعا الإنسان في السجود فيما يتعلق بالآخرة والدنيا فلا بأس، اللهم اغفر لي وارحمني، اللهم أصلح ذريتي، اللهم أصلح زوجي، اللهم اغفر لوالدي، اللهم ارزقني رزقًا حلالًا.. إلى غير هذا نعم، كله طيب في السجود. نعم.\nالمقدم: أحسن الله إليكم يا سماحة الشيخ.","link":"https://binbaz.org.sa/fatwas/16786/حكم-الدعاء-بامر-دنيوي-اثناء-السجود","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_778/nour_77813.mp3","categories":["الأدعية والأذكار","التكبير والاستفتاح","الركوع والسجود"]},{"id":17802,"question":"من أسئلة السائل أبو عبد الله من القصيم يقول: إذا دعا الإنسان في الركوع ناسيًا، هل يجوز له ذلك؟","title":"حكم الدعاء في الركوع","answer":"الجواب: لا حرج عليه، إذا دعا لا حرج عليه، لكن لا يتعمد ذلك، يقول النبي ﷺ: أما الركوع فعظموا فيه الرب، وأما السجود فاجتهدوا في الدعاء فالدعاء يكون في السجود، والركوع يكون فيه تعظيم الرب: (سبحان ربي العظيم، سبحان ربي العظيم، سبحانك اللهم ربنا وبحمدك اللهم اغفر لي، سبوح قدوس رب الملائكة والروح)، فهذا هو المشروع في الركوع، قوله: (سبحانك اللهم ربنا وبحمدك اللهم اغفر لي)، هذه دعوة تابعة للتسبيح، فيكثر من التسبيح، أما الدعاء فيكثر منه في السجود محله السجود. نعم.\nالمقدم: أحسن الله إليكم.","link":"https://binbaz.org.sa/fatwas/16784/حكم-الدعاء-في-الركوع","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_597/59713.mp3","categories":["الأدعية والأذكار","التكبير والاستفتاح","الركوع والسجود"]},{"id":18157,"question":"هذه سائلة من الرياض ذكرت هذا الرمز تقول: نعلم وجوب السجود على الأعضاء السبعة، ولكنني يا سماحة الشيخ أحيانًا لا أنتبه أو لا أتنبه بعدم سجودي على الأعضاء السبعة كاملة؛ لوجود حائل لم أزله إلا بعد الانتهاء من السجود، فهل علي شيء من ذلك؟","title":"حكم السجود على الأعضاء السبعة","answer":"الجواب: الواجب السجود على الأعضاء السبعة، لا يصح السجود إلا بذلك، فإذا كان السجود على فراش أو على بساط، أو على غير ذلك؛ فلا بأس ما يضر، ما هو بلزوم يباشر الأرض، إذا سجد على مطرحة، أو على زولية، أو على بساط، أو على غيرها؛ لا بأس. أما إذا رفع أحد الأعضاء سجد على ستة، أو خمسة؛ ولم يضع يده على الأرض أو يديه أو وجهه ما يصح السجود، لا بد أن يضع وجهه على الأرض، سواء الأرض فيها بساط، أو ما فيها بساط للأرض جبهته، وأنفه، وكفيه على الأرض، قدميه، ركبتيه؛ هذه السبعة، فإذا رفع يده، أو وجهه، ولم يسجد ما يسمى ساجد، حتى يضع وجهه على الأرض ويديه على الأرض، وركبتيه على الأرض، وقدميه على الأرض .. على بطون أصابعه، هذا هو السجود الشرعي. فلو سجد وهو رافع يده أو رجله لم يصح السجود، أو سجد في الهواء وهو قادر على الأرض ما هو بمريض، يستطيع السجود على الأرض، وسجد ولكن لم يصل وجهه إلى الأرض؛ ما يصح السجود. نعم. المقدم: شكر الله لكم يا سماحة الشيخ، وبارك الله فيكم وفي علمكم، ونفع بكم المسلمين.","link":"https://binbaz.org.sa/fatwas/17207/حكم-السجود-على-الاعضاء-السبعة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_781/nour_78123.mp3","categories":["الأدعية والأذكار","التكبير والاستفتاح","الركوع والسجود"]},{"id":18175,"question":"ما حكم من يصلي على أنفه، ولم يمكن جبهته؟ هل تبطل الصلاة؟","title":"حكم صلاة من يسجد على أنفه ولا يمكن جبهته","answer":"الجواب: نعم، ما تصح الصلاة، ما يصح السجود، إذا تعمد ذلك يكون السجود باطلًا، أما إن كان ناسيًا، فيعيد السجدة، يعيد السجدة إن كان مازال في السجدة، يعيدها، وإن كان قد قام، وقرأ، تبطل الركعة، ويأتي بركعة بدلًا منها؛ لأن هذه الركعة بطلت ببطلان السجود، لابد أن يسجد على الجبهة والأنف جميعًا، أما إذا تنبه في الحال؛ فإنه يعيد السجود، يعيد السجود في الحال قبل أن يقوم. نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/17215/حكم-صلاة-من-يسجد-على-انفه-ولا-يمكن-جبهته","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_731/nour_73110.mp3","categories":["الأدعية والأذكار","التكبير والاستفتاح","الركوع والسجود"]},{"id":18305,"question":"يقول السائل هذا يا سماحة الشيخ! ما حكم من يصلي وهو واضع العمامة على الجبهة، حتى تصل إلى حاجب العين، أي: أنه مغطي موضع السجود وهو الجبهة؟","title":"حكم السجود على كور العمامة","answer":"الجواب: الصلاة صحيحة، لكن الأفضل أن يرفع العمامة ويسجد على المصلى، ولو سجد على عمامته أو على طرف بشته لا بأس، لكن الأفضل أن تكون جبهته على المصلى هذا هو الأفضل.","link":"https://binbaz.org.sa/fatwas/17353/حكم-السجود-على-كور-العمامة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_913/nour_91302.mp3","categories":["الأدعية والأذكار","التكبير والاستفتاح","الركوع والسجود"]},{"id":18414,"question":"يقول سماحة الشيخ: في دعاء الاستفتاح استفتاح صلاة الليل هل نردده في كل ركعتين، وهل نردده في الركعتين التي يقرأ فيهما بـ: سَبِّحِ اسْمَ رَبِّكَ الأَعْلَى[الأعلى:1] وقُلْ يَا أَيُّهَا الْكَافِرُونَ[الكافرون:1] وكذلك في الركعة التي يقرأ فيها قُلْ هُوَ اللَّهُ أَحَدٌ[الإخلاص:1] ؟","title":"من أحكام دعاء الاستفتاح","answer":"الجواب: نعم، السنة الاستفتاح في كل الصلوات: سبحانك اللهم وبحمدك، وتبارك اسمك، وتعالى جدك، ولا إله غيرك في جميع الصلوات في التراويح وغير التراويح، مستحب، ولو ترك فلا بأس لكن مستحب إذا كبر تكبيرة الإحرام في كل تسليمة يقول: سبحانك اللهم.. لأنه مختصر، هذا استفتاح مختصر، وإن استفتح بغيره من الاستفتاحات الصحيحة الثابتة عن رسول الله فلا بأس، ولو ترك فلا حرج. لكن إذا أتى به الإمام والمأموم فهذا أفضل، وإن كان الإمام شرع في القراءة فإن المأموم لا يستفتح ينصت، لكن لو سكت الإمام بعد تكبيرة الإحرام فالسنة أن يأتي بالاستفتاح الإمام والمأموم، لكن لو شرع الإمام بعدما كبر ولم يستفتح فالمأموم ينصت ولا يستفتح؛ لقوله ﷺ: وإذا قرأ فأنصتوا. نعم. المقدم: أحسن الله إليكم سماحة الشيخ.","link":"https://binbaz.org.sa/fatwas/17493/من-احكام-دعاء-الاستفتاح","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_784/nour_78418.mp3","categories":["التكبير والاستفتاح","النية في الصلاة"]},{"id":18564,"question":"أخونا يسأل هذا السؤال ويقول: أيهما أرجح: الهوى إلى السجود باليدين، أم بالركبتين؟","title":"الأرجح في كيفية الهوي إلى السجود","answer":"الجواب: هذا محل اختلاف بين العلماء، والأفضل والأرجح الهوي بالركبتين ثم اليدين، ركبتيه، يعني: يقدم ركبتيه ثم يديه ثم جبهته وأنفه، هذا هو الأفضل على حديث وائل بن حجر وما جاء في معناه، ومن قدم يديه فالأمر واسع -إن شاء الله-؛ لأن فيه حديث أبي هريرة أيضًا، ولكن الصواب أنه يقدم ركبتيه، ثم يديه ثم جبهته وأنفه. وأما حديث أبي هريرة الذي فيه: وليضع يديه قبل ركبتيه فهو فيه انقلاب كما حققه بعض أهل العلم؛ لأن أول الحديث يقول ﷺ: لا يبرك أحدكم كما يبرك البعير  والبعير يقدم يديه، فإذا قدمنا أيدينا صرنا مشابهين للبعير، فيكون آخر الحديث يخالف أوله، فيكون الصواب: (وليضع ركبتيه قبل يديه) على حديث وائل وعلى موافقة صدر الحديث، فحصل انقلاب (فليضع يديه قبل ركبتيه). المقصود: أن الأرجح أن يقدم ركبتيه قبل يديه، وأن الأرجح في حديث أبي هريرة أنه موافق لحديث وائل، وأن ما في آخره من ذكر اليدين قبل الركبتين انقلاب من بعض الرواة، وهو الأقرب والأظهر حتى لا يخالف آخر الحديث أوله، وحتى تجتمع الأحاديث عن النبي ﷺ وهذا هو الذي عليه جمهور أهل العلم وأكثر أهل العلم. ومن ترجح عنده تقديم اليدين واجتهد في ذلك فلا ينبغي أن ينكر عليه، ينبغي في هذا عدم التشديد، وعدم النزاع والخلاف، فالمؤمن يتحرى الحق، فالأرجح والأظهر والأقرب أن يقدم ركبتيه ثم يديه ثم جبهته مع أنفه، هذا في السجود، وعند الرفع يبدأ بالوجه ثم اليدين ثم ينهض على ركبتيه، هذا هو الأفضل، وهذا هو الذي به الجمع بين الأحاديث، نعم. المقدم: بارك الله فيكم.","link":"https://binbaz.org.sa/fatwas/17678/الارجح-في-كيفية-الهوي-الى-السجود","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_917/nour_91706.mp3","categories":["الأدعية والأذكار","التكبير والاستفتاح","الركوع والسجود"]},{"id":18629,"question":"هذا سائل للبرنامج نور الدين له مجموعة من الأسئلة، يقول في السؤال الأول: ما حكم السجود على العمامة؟ وهل يجوز السجود عليها؟","title":"حكم السجود على العمامة","answer":"الجواب: الأفضل يسجد على المصلى، هذا الأفضل، يسجد على المصلى لا على العمامة، ولا..، بل على المصلى، سواء المصلى سجادة أو بساط، أو حصباء، أو رمل؛ يسجد مع الناس على المصلى، فلو سجد على أطراف العمامة ما يضر، لو وضع جبهته على أطراف العمامة أو الغترة، أو بشت، أو غيره ما يضر، لكن كونه يسجد على المصلى الذي يصلي عليه الناس، أو مصلاه الذي هو يصلي عليه في بيته أفضل، يباشر المصلى بجبهته وأنفه. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/17743/حكم-السجود-على-العمامة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_787/nour_78712.mp3","categories":["الأدعية والأذكار","التكبير والاستفتاح","الركوع والسجود"]},{"id":18656,"question":"من القصيم هذه رسالة بعثت بها إحدى الأخوات تقول المرسلة: (ع. ل. هـ) أختنا تسأل وتقول: لقد كنت في صلاتي أثناء الرفع من الركوع أقول: ربنا ولك الحمد، دون أن أقول: سمع الله لمن حمده، ولكنني بعد ذلك سمعت أنه لا يجوز ذلك، بل لا بد أن أقول: سمع الله لمن حمده، فهل علي إثم وذنب في صلواتي التي مضت، مع العلم بأنني لم أكن أعلم بأن قول: (سمع الله لمن حمده) واجب في الصلاة؟ وإذا كان علي شيء فماذا أفعل؟أفيدوني، جزاكم الله خيرًا.","title":"حكم ترك: (سمع الله لمن حمده) بعد الرفع من الركوع","answer":"الجواب: نرجو ألا يكون عليك شيء؛ لأجل الجهل، وعليك مع ذلك الاستغفار والتوبة والندم على ما حصل من التساهل، وعدم السؤال؛ لأن الواجب على من جهل شيئًا أن يسأل أهل العلم في صلاته وغيرها، وما مضى صحيح والحمد لله، وعليك في المستقبل أن تقولي: (سمع الله لمن حمده) عند الرفع من الركوع. وهكذا الإمام وهكذا المنفرد من الرجال، كل واحد يقول: سمع الله لمن حمده.  أما المأموم فيقول: ربنا ولك الحمد، هذا هو الصواب، وليس عليه أن يقول: (سمع الله لمن حمده) ولا يشرع له ذلك، إنما هذا من شأن الإمام والمنفرد من الرجال والنساء، عند الرفع يقول: سمع الله لمن حمده، وعند الاستواء يقول: ربنا ولك الحمد، أو اللهم ربنا لك الحمد، وما مضى نسأل الله أن يعفو عنا وعنك، والصلاة صحيحة -إن شاء الله- من أجل الجهل، ولكن في المستقبل عليك أن تجتهدي في ذلك، وأن تستمري عليه، وأن لا تتركي هذه الكلمة: (سمع الله لمن حمده) إذا كنت منفردة، أما مع الإمام فتقولي: (ربنا ولك الحمد) إذا صليت مع الإمام تقولي: ربنا ولك الحمد، أو اللهم ربنا لك الحمد، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/17766/حكم-ترك-سمع-الله-لمن-حمده-بعد-الرفع-من-الركوع","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_919/nour_91906.mp3","categories":["الأدعية والأذكار","التكبير والاستفتاح","الركوع والسجود"]},{"id":18747,"question":"خالد سليمان مصري، ويعمل في دولة قطر، أرسل إلى البرنامج بمجموعة من الأسئلة، يبدأ هذه الرسالة بهذا السؤال ويقول: سماحة الشيخ، هل تجوز الصلاة على النبي ﷺ في السجود أو في الصلاة؟","title":"حكم الصلاة على النبي ﷺ في السجود","answer":"الجواب: نعم، إذا صلى على النبي ﷺ في السجود قبل الدعاء مستحب، يحمد الله، ويصلي على النبي ﷺ ويدعو في السجود، وفي آخر الصلاة قبل أن يسلم، وفي دعواته الأخرى خارج الصلاة يحمد الله، ويصلي على النبي ﷺ ويدعو؛ لقوله ﷺ في حديث فضالة بن عبيد: إذا صلى أحدكم فليبدأ بتحميد ربه، والثناء عليه، ثم يصلي على النبي ﷺ ثم يدعو بما شاء هذا هو السنة؛ أن يبدأ بالحمد والثناء والصلاة على النبي ﷺ ثم يدعو، ولو في السجود، أو في آخر الصلاة، أو في أي وقت آخر غير الصلاة، نعم.","link":"https://binbaz.org.sa/fatwas/17859/حكم-الصلاة-على-النبي-ﷺ-في-السجود","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_789/nour_78911.mp3","categories":["الأدعية والأذكار","التكبير والاستفتاح","الركوع والسجود"]},{"id":18924,"question":"سماحة الشيخ، هل يكتفي المصلي بدعاء الاستفتاح مرة واحدة، أم أنه يجب عليه أن يدعو بعد كل تسليمتين كصلاة الليل مثلاً؟","title":"مشروعية الاستفتاح في كل تسليمة","answer":"الجواب: مستحب الاستفتاح، ما هو بواجب، مستحب في كل تسليمة قبل أن يقرأ، يقول: سبحانك اللهم وبحمدك، وتبارك اسمك، وتعالى جدك، ولا إله غيرك أو يأتي بنوع آخر من الاستفتاحات قبل أن يقرأ، هذا هو الأفضل، ولو تركه فلا شيء عليه في كل تسليمة.","link":"https://binbaz.org.sa/fatwas/18075/مشروعية-الاستفتاح-في-كل-تسليمة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_882/nour_88211.mp3","categories":["التكبير والاستفتاح","النية في الصلاة"]},{"id":19132,"question":"من صديق البرنامج كما وصف نفسه المستمع (ع. ع. س) من ليبيا رسالة وضمنها جمعًا من الأسئلة، في أحدها يقول: عندنا في المسجد إمام، وهذا الإمام يصلي بنا وهو سريع في صلاته، وعند السجود يسبق اليدين قبل الركبتين، ونحن مجموعة شباب نخالفه في سجوده فنسبق الركبتين قبل اليدين بدليل: \"لا تشبهوا سجودكم بالبعير\"، فهل هذا السجود صحيح؟ وجهونا مأجورين جزاكم الله خيرًا.","title":"حكم تقديم اليدين على الركبتين حال الهوي إلى السجود","answer":"الجواب: سجودكم جميعًا صحيح، سجوده صحيح، وسجودكم صحيح، والحمد لله، لكن الأفضل مثلما فعلتم تقديم الركبتين على اليدين كما جاء في حديث وائل وغيره وهو موافق لحديث أبي هريرة الذي فيه النهي عن البروك كبروك البعير؛ لأن بروك البعير يقدم يديه، فالسنة أن يقدم الركبتان، أن تقدم الركبتان لأنهما في الرجلين قبل اليدين. وذهب بعض أهل العلم إلى تقديم اليدين قبل الركبتين؛ لأن في حديث أبي هريرة : وليضع يديه قبل ركبتيه، وتأولوا ذلك على أن بروك البعير على ركبتيه وهما في يديه، فإذا قدم المصلي يديه فقد خالف البعير، وليس الأمر كذلك، الصحيح أن بروك الإنسان على يديه هو الذي يشبه البعير، ويخالف أول الحديث لا يبرك كما يبرك البعير ويخالف حديث وائل: \"رأيت النبي ﷺ إذا سجد وضع ركبتيه قبل يديه\" هذا هو الأفضل وهذا هو الأشهر. ومن اعتقد ما دل عليه آخر حديث أبي هريرة: وليضع يديه قبل ركبتيه من اعتقد هذا ووضع يديه قبل ركبتيه عن اجتهاد منه فلا حرج عليه، والله يغفر للجميع، لكن الأفضل هو تقديم الركبتين قبل اليدين هذا هو الأرجح، وهذا هو الأفضل، ومن قدم يديه قبل ركبتيه معتقدًا أن هذا هو الأفضل حسب اجتهاده وعلمه فلا شيء عليه، المصيب له أجران، والمخطي له أجر واحد، والحمد لله، هذا كله إذا كان يستطيع تقديم الركبتين، أما إذا كان عاجزًا لكبر سنه، أو مرضه؛ فإنه يقدم يديه، ولا شيء عليه، والحمد لله. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/18348/حكم-تقديم-اليدين-على-الركبتين-حال-الهوي-الى-السجود","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_798/nour_79805.mp3","categories":["الأدعية والأذكار","التكبير والاستفتاح","الركوع والسجود"]},{"id":19194,"question":"رسالة من أحد الإخوة المستمعين يقول اسمي هشام عبدالرحمن من السودان الخرطوم، أخونا له عدد من الأسئلة من بينها سؤال يقول: قد ذكرت -يحفظكم الله- أن صفة صلاة النبي ﷺ أن ينزل الإنسان من الركوع إلى السجود على ركبتيه، وينهض إلى الركعة برفع يديه قبل ركبتيه، لكن بعض الباحثين ذكر عكس ذلك، فأي القولين نعتمد، وبأيهما نعمل؟ جزاكم الله خيرًا.","title":"الصواب في كيفية الهوي في السجود في الصلاة","answer":"الجواب: للعلماء قولان في المسألة -رحمهم الله- منهم من رجح أنه ينزل بركبتيه، ثم يديه، ثم جبهته وأنفه؛ لما روى أهل السنن عن وائل بن حجر  عن النبي ﷺ أنه رأى النبي ﷺ إذا سجد قدم ركبتيه على يديه، وله شاهد من حديث أنس أيضًا عند الحاكم وغيره، وقالوا: هذا هو الأرفق بالمصلي وهو الأبعد عن مشابهة الحيوان؛ لأن الحيوان كالبعير ينزل على يديه ثم مؤخره بعد ذلك، وقالوا: هو الموافق لحديث أبي هريرة  عن النبي ﷺ أنه قال: لا يبرك أحدكم كما يبرك البعير فإن بروك البعير يقدم يديه، فإذا قدم رجليه لم يشبه البعير. أما قوله في آخره: وليضع يديه قبل ركبتيه فقال بعضهم: لعله مقلوب، وأن الصواب وليضع ركبتيه قبل يديه حتى يتفق أوله مع آخره، أول الحديث مع آخر الحديث، وحتى يتفق مع حديث وائل بن حجر وأنس وما جاء في معناهما، وهذا هو الأصح والأرجح، وبذلك تتفق الأحاديث ولا يقع بينها خلاف، فالنهي عن بروك كبروك البعير يوافق حديث وائل في تقديم الركبتين ثم اليدين بعد ذلك في السجود. أما زيادة: وليضع يديه قبل ركبتيه فهي تخالف أول الحديث، وتخالف حديث وائل؛ لأنه إذا وضع يديه قبل ركبتيه شابه البعير في نزوله على مقدمه، هذا هو الأرجح. وقال آخرون من أهل العلم: لفظة: وليضع يديه صريحة تدل على أنه يقدم يديه على ركبتيه، وبهذا خالفوا حديث وائل وهو حديث لا بأس به حديث حسن جيد، مع أنه موافق لأول حديث أبي هريرة ولمقدمه وصدره. والصواب عندي والأرجح عندي أنه يقدم ركبتيه ثم يديه، ثم جبهته وأنفه على ما في حديث وائل، وعلى مقتضى أول حديث أبي هريرة وصدره، وزيادة: وليضع يديه قبل ركبتيه هذه إما إدراج من بعض الرواة، وإما حصل فيها انقلاب والصواب: وليضع ركبتيه قبل يديه حتى يتفق أوله مع آخره، وحتى يتفق مع حديث وائل وما جاء في معناه، والأمر في هذا واسع والحمد لله كله سنة، لكن هذا هو الأفضل وهذا هو الأرجح، إلا من عجز ككبير السن والمريض هذا يقدم يديه؛ لأنه محتاج إلى ذلك ولا بأس بذلك. نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/18424/الصواب-في-كيفية-الهوي-في-السجود-في-الصلاة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_799/nour_79904.mp3","categories":["الأدعية والأذكار","التكبير والاستفتاح","الركوع والسجود"]},{"id":19294,"question":"المستمعة (ع. س) من الرياض بعثت برسالة وضمنتها عدداً من الأسئلة، عرضنا معظم أسئلتها في حلقات مضت، وبقي لها في هذه الحلقة سؤالان، السؤال الأول يقول: هل يجوز أن نصلي على النبي ﷺ في السجود؟ جزاكم الله خيرًا.","title":"حكم الصلاة على النبي صلى الله عليه وسلم في السجود","answer":"الجواب: نعم، نصلي عليه هذا دعاء، الصلاة على النبي ﷺ دعاء، والنبي عليه الصلاة والسلام قال: أقرب ما يكون العبد من ربه وهو ساجد فأكثروا الدعاء رواه مسلم في الصحيح، وقال عليه الصلاة والسلام: أما الركوع فعظموا فيه الرب، وأما السجود فاجتهدوا في الدعاء فقمن أن يستجاب لكم يعني: فحري أن يستجاب لكم، رواه مسلم أيضًا في صحيحه. وكان النبي يدعو في سجوده عليه الصلاة والسلام، ويلح في الدعاء، فإذا حمدت الله في سجودك، وصليت على النبي ﷺ فهذا من أسباب الإجابة: سبحان ربي الأعلى، سبحان ربي الأعلى، سبحانك اللهم ربنا وبحمدك اللهم اغفر لي هذا ثناء على الله، سبوح قدوس رب الملائكة والروح، هذا يقال في السجود وفي الركوع جميعًا، ويختص السجود بـ سبحان ربي الأعلى، والركوع يختص بـ سبحان ربي العظيم، أما سبوح قدوس رب الملائكة والروح هذا في السجود والركوع جميعًا، وهكذا سبحانك اللهم ربنا وبحمدك اللهم اغفر لي هذا يقال في السجود والركوع جميعًا. وإذا صليت على النبي ﷺ بعد ذلك في السجود قلت: اللهم صل على محمد وعلى آل محمد كما صليت على إبراهيم وآل إبراهيم إنك حميد مجيد، اللهم بارك على محمد وعلى آل محمد كما باركت على إبراهيم وعلى آل إبراهيم إنك حميد مجيد ثم دعوت الله بعد ذلك هذا من أسباب الإجابة، دعوت للنبي ﷺ هذا قربة منك تتقرب بها إلى الله، وإحسان لنبيك عليه الصلاة والسلام؛ تدعو له في الصلاة أن الله يثني عليه ويرحمه، وهكذا لو قلت: اللهم صل وسلم على الرسول باختصار، اللهم صل وسلم على رسول الله مختصرًا كفى، وإن كملتها كما جاءت في الأحاديث الصحيحة فهو أفضل وأكمل. ثم تدعو بما تشاء: اللهم اغفر لي ذنبي كله دقه وجله، وأوله وآخره، وعلانيته وسره هذا من دعاء النبي ﷺ في السجود كان يدعو بهذا الدعاء عليه الصلاة والسلام، وإذا دعوت بغير هذا: اللهم إني أسألك رضاك والجنة وأعوذ بك من سخطك والنار، اللهم أصلح قلبي وعملي، وارزقني الفقه في ديني، رب زدني علمًا، اللهم اجعلني من الهداة المهتدين، اللهم اغفر لي ولوالدي ولجميع المسلمين، وما أشبهه تدعو ربك تسأل ربك، اللهم اشرح لي صدري، ويسر لي أمري، واجعلني مباركاً أينما كنت. اللهم أصلح أحوال المسلمين، اللهم أصلح ولاة المسلمين، اللهم وفقهم لما يرضيك ... إلى غير هذا من الدعوات الطيبة في سجودك، كل هذا مشروع وحري بالإجابة ولاسيما إذا كان معه التسبيح والتحميد، والصلاة على النبي ﷺ قل أن تدعوه، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/18457/حكم-الصلاة-على-النبي-صلى-الله-عليه-وسلم-في-السجود","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_800/nour_80005.mp3","categories":["الأدعية والأذكار","التكبير والاستفتاح","الركوع والسجود"]},{"id":19442,"question":"رسالة وصلت إلى البرنامج من أحد الإخوة المستمعين ضمنها بعضًا من الأسئلة، والمستمع هو العبد الله أبو عبد الرحمن الطاهر بن عثمان بن علي، أخونا يسأل عن التكبيرة في السجود متى تكون، هل عندما يكون قد سجد في الأرض، أو عندما يكون هاويًا إلى السجود؟","title":"وقت التكبير للسجود","answer":"الجواب: التكبير للسجود عند الهوي يكبر حال هويه إلى الأرض يقول: الله أكبر حين يشرع في الهوي ويقطعها قبل أن يصل إلى الأرض، وعند الرفع كذلك إذا رفع يكبر حين رفعه وينتهي قبل استتمامه قائمًا، وهكذا إذا كان جالسًا إذا رفع من السجدة الأولى كبر حين رفعه من السجدة الأولى قبل أن يستتم جالسًا هكذا المشروع يكبر حين الرفع وحين النزول للسجود، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/18682/وقت-التكبير-للسجود","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_938/nour_93807.mp3","categories":["الأدعية والأذكار","التكبير والاستفتاح","الركوع والسجود"]},{"id":19446,"question":"في أثناء الصلاة وأنا أريد السجود هل أنزل باليدين أم أنزل بالركبتين؟","title":"مشروعية النزول على الركبتين عند الهوي إلى السجود","answer":"الجواب: الأفضل نزولك بالركبتين هذا هو الأفضل كان النبي ﷺ إذا سجد سجد على ركبتيه، ثم يديه، ثم جبهته وأنفه إلا إذا كان هناك عجز كمرض أو كبر سن فلا بأس أن تسجد على يديك أولًا وتنهض عليهما للعجز والضعف، وذهب بعض أهل العلم إلى أنه يسجد على يديه مطلقًا ولكنه قول مرجوح. والصواب أن الأحاديث كلها في المعنى تدل على أنه يسجد على ركبتيه أولاً، ثم يديه، ثم جبهته وأنفه، هذا عند السجود، وعند الرفع يرفع رأسه أولاً ثم يديه ثم ركبتيه، إلا العاجز لمرض أو كبر سن فهذا لا بأس أن يسجد على يديه وينهض على يديه. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/18683/مشروعية-النزول-على-الركبتين-عند-الهوي-الى-السجود","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_938/nour_93808.mp3","categories":["الأدعية والأذكار","التكبير والاستفتاح","الركوع والسجود"]},{"id":19566,"question":"هذه الأخت السائلة من القصيم البدائع (ع. م. ع) الحربي تقول: يا سماحة الشيخ! أنا أثناء صلاة التهجد أطيل في السجود وأحس بتعب في الأيدي والصدر، هل يجوز لي أن أضع مخدة تحت الصدر وأكواع اليدين؟","title":"حكم وضع مخدة تحت الصدر عند السجود لمن يطيله","answer":"الجواب: ما أعرف لهذا أصل، لكن المشروع عدم التكلف، لا تطيل في السجود حتى لا تكلف، أما وضعها هذه الأشياء ما أعرف لها أصلا ، لكن السنة عدم التكلف، تسجد حسب طاقتها ولا تتكلف. نعم.","link":"https://binbaz.org.sa/fatwas/18831/حكم-وضع-مخدة-تحت-الصدر-عند-السجود-لمن-يطيله","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_947/nour_94720.mp3","categories":["الأدعية والأذكار","التكبير والاستفتاح","الركوع والسجود"]},{"id":19574,"question":"في سؤالها الثاني تقول هذه السائلة من أبها: يا سماحة الشيخ في الصلاة عندما أرفع من الركوع، وأريد السجود؛ متى أكبر، هل عندما أنحني أم عندما أضع ركبتي على الأرض؟","title":"مشروعية التكبير عند الانحناء إلى السجود","answer":"الجواب: عند الانحناء، عند الانحناء تكبر، قبل أن تصل الأرض، تكبرين إذا انحنيت قبل الوصول إلى الأرض. نعم. المقدم: حفظكم الله.","link":"https://binbaz.org.sa/fatwas/18837/مشروعية-التكبير-عند-الانحناء-الى-السجود","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_947/nour_94723.mp3","categories":["الأدعية والأذكار","التكبير والاستفتاح","الركوع والسجود"]},{"id":19598,"question":"تقول السائلة: هل يشترط لدعاء السجود في صلاة الفريضة أن يبدأ بالحمد لله، والصلاة على النبي ﷺ؟","title":"حكم ابتداء الدعاء في الصلاة بالحمد لله والصلاة على النبي ﷺ","answer":"الجواب: لا ما هو بشرط، يدعو بما تيسر، وإن حمد الله، وصلى على النبي ﷺ فلا بأس، كله طيب، هذا من أسباب الإجابة، وإن دعا فقط ولم يحمد الله، ولم يصل على النبي ﷺ بل دعا وقال: «سبحان ربي الأعلى، سبحان ربي الأعلى» ودعا اللهم اغفر لي وارحمني، واهدني وارزقني، وعافني، اللهم أدخلني الجنة، وأنجني من النار، اللهم أصلح قلبي وعملي، اللهم اغفر لي ولوالدي كله طيب. المقدم: حفظكم الله سماحة الشيخ.","link":"https://binbaz.org.sa/fatwas/18859/حكم-ابتداء-الدعاء-في-الصلاة-بالحمد-لله-والصلاة-على-النبي-ﷺ","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_948/nour_94801.mp3","categories":["الأدعية والأذكار","التكبير والاستفتاح","الركوع والسجود"]},{"id":19615,"question":"يقول هذا السائل يا سماحة الشيخ: ما حكم من يقول قبل تكبيرة الإحرام: وجهت وجهي للذي فطر السموات والأرض حنيفًا وما أنا من المشركين هل هذا وارد؟","title":"حكم الإتيان بدعاء الاستفتاح قبل تكبيرة الإحرام","answer":"الجواب: لا، هذا بعد التكبير، هذا من أنواع الاستفتاح يقوله بعد التكبير لا قبل التكبير؛ لأن الاستفتاح أنواع منها هذا، ومنها الاستفتاح المختصر: سبحانك اللهم وبحمدك، وتبارك اسمك، وتعالى جدك، ولا إله غيرك. ومنها: اللهم باعد بيني وبين خطاياي كما باعدت بين المشرق والمغرب، اللهم نقني من خطاياي كما ينقى الثوب الأبيض من الدنس، اللهم اغسلني من خطاياي بالثلج، والماء، والبرد، ومنها أنواع أخرى.","link":"https://binbaz.org.sa/fatwas/18889/حكم-الاتيان-بدعاء-الاستفتاح-قبل-تكبيرة-الاحرام","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_948/nour_94820.mp3","categories":["التكبير والاستفتاح","النية في الصلاة"]}]
